-- Factory modules (#350; owner 2026-11-03: "factory modules should be protected by read-only. so if some one wants to
-- create a derivative, they can do so"): the modules we built – walk, analog, fixture (deck/modules/<id>/src/*.rs) – become
-- catalog documents `module:<id>` marked `factory: true`. Nobody edits one in place (the API answers 403 factory_module to a
-- draft, a publish, a restore, a compile into it, an admin write or delete); a member derives a module of their own from it
-- (a new `module:<id>` draft with `origin` = the factory id). Sources only: `files` are the repository's files byte for byte
-- (server tests/Unit/Domain/FactoryModulesTest keeps them equal; analog is flat files since #350 – the build service takes
-- flat `src/*.rs` only).
-- The wasm: NOT in this file. A factory module reads as not compiled (no descriptor / wasm, so it is no kind in
-- GET /api/kinds yet) until the build service compiles it once: an admin presses Compile on module:walk / analog / fixture
-- in the creator's Sound workspace (POST /api/modules/compile { factory: "<id>" }, no files) – ModuleCompiler writes the
-- descriptor and the wasm hash straight into the catalog entry (the .wasm on the CDN as modules/<hash>.wasm), the sources
-- stay as they are. Why not CI: the wasm's bytes (and so its hash and CDN path) are the service's pinned toolchain's; a CI
-- build would be a second toolchain and would need the CDN's credentials in the workflow.
-- What it touches:
--   catalog_modules: three rows, INSERT IGNORE – an existing row with one of these ids (a module a creator made under the
--     name) is left as it is, and then that id is not a factory module (the dry run below shows it; tell the owner).
--   entity_versions: the factory content as the published version of `module:<id>` (message = the marker below), so the
--     creator opens it like any document; a published version of such a key from before becomes a draft (history).
-- Dry run (before): SELECT id, JSON_EXTRACT(data, '$.factory') AS factory FROM catalog_modules WHERE id IN ('walk', 'analog', 'fixture');
--   → expected: no rows. SELECT entity_key, status, COUNT(*) FROM entity_versions WHERE entity_key IN ('module:walk',
--   'module:analog', 'module:fixture') GROUP BY entity_key, status; → expected: no rows (else: drafts that become history).
-- Test (after): SELECT id, JSON_EXTRACT(data, '$.factory'), JSON_LENGTH(data, '$.files') FROM catalog_modules WHERE id IN
--   ('walk', 'analog', 'fixture'); → walk true 1, analog true 11, fixture true 1; and one published entity_versions row each.
-- Plan's row counts on a database without them: 3 · 0 · 3. MariaDB 10.11, idempotent: a second run changes nothing
-- (INSERT IGNORE; the published marker version exists). Escaping: plain string literals (no NO_BACKSLASH_ESCAPES): `\\` is
-- one backslash of the JSON, `\'` a quote; each row is one line.

INSERT IGNORE INTO `catalog_modules` (`id`, `position`, `data`, `updated_at`, `updated_by`) VALUES
  ('walk', 0, '{"id":"walk","name":"walk","factory":true,"files":{"lib.rs":"//! `walk` as a module (#280; module ABI v2 #343) – the stage\'s built-in `walk` node (deck-events\' `random_walk` into\\n//! seq\'s cv) written against the SDK, the example of one: a seeded random walk on a continuous pitch scale, on the tempo\\n//! clock. `spread` 0 = the base held, 1 = ±`octaves`; `rate` = steps a beat; `glide` rides along for the voice. The same\\n//! seed plays the same melody on every deck, however the timeline is cut into blocks. Every step is a `music.note` on\\n//! the `notes` event output (a note on with its pitch in Hz, its length in beats and its glide – an instrument with a\\n//! note input, `analog`, plays it); the same notes are rendered into the `cv` output, pitch (Hz) on the left and the gate\\n//! on the right – an fm / osc voice with its `cv` linked plays that.\\n//!\\n//! Build: `cargo build --release --target wasm32-unknown-unknown -p walk-module` (the .wasm in\\n//! `target/wasm32-unknown-unknown/release/walk_module.wasm`).\\n// one `#[port(…)]` a port: clippy takes them for duplicates (deck/module/README.md)\\n#![allow(clippy::duplicated_attributes)]\\nuse deck_module::cv::GateCv;\\nuse deck_module::{math, Block, Ctx, Ev, Module};\\n\\n#[derive(Module)]\\n#[module(name = \\"walk\\", doc = \\"a seeded random walk on a continuous pitch scale, on the tempo clock\\")]\\n#[port(output, cv, name = \\"cv\\", doc = \\"pitch in Hz left, the gate right\\")]\\n#[port(output, event, name = \\"notes\\", names = \\"music.note\\", props = \\"pitch|vel|glide\\", capacity = 64, doc = \\"every step as a note\\")]\\npub struct Walk {\\n    #[param(range = 0.0..1.0, default = 0.0, doc = \\"0 = the base held, 1 = ±octaves\\")]\\n    spread: f32,\\n    #[param(range = 0.0..16.0, default = 2.0, unit = \\"steps/beat\\", doc = \\"steps a beat\\")]\\n    rate: f32,\\n    #[param(range = 0.0..1.0, default = 0.5, doc = \\"of a note\'s length: how long the voice glides into it\\")]\\n    glide: f32,\\n    #[param(range = 20.0..2000.0, default = 147.0, unit = \\"Hz\\", doc = \\"the pitch the walk centres on\\")]\\n    base: f32,\\n    #[param(range = 0.0..4.0, default = 2.0, unit = \\"oct\\", doc = \\"how far a full spread reaches either way\\")]\\n    octaves: f32,\\n    #[param(range = 0.0..1.0, default = 1.0, doc = \\"of a step: how long the note holds\\")]\\n    length: f32,\\n    cv: Option<GateCv>,\\n}\\n\\n/// a uniform number in [0, 1) for (seed, step) – splitmix64, so step k\'s value never depends on the steps before\\nfn unit(seed: u64, step: i64) -> f64 {\\n    let mut z = seed ^ (step as u64).wrapping_mul(0x9E37_79B9_7F4A_7C15);\\n    z = (z ^ (z >> 30)).wrapping_mul(0xBF58_476D_1CE4_E5B9);\\n    z = (z ^ (z >> 27)).wrapping_mul(0x94D0_49BB_1331_11EB);\\n    z ^= z >> 31;\\n    (z >> 11) as f64 / (1u64 << 53) as f64\\n}\\n\\n/// the steps on a grid of `per_beat` steps a beat whose start falls in [from, to): (step, its beat)\\nfn steps(from: f64, to: f64, per_beat: f64) -> impl Iterator<Item = (i64, f64)> {\\n    let ok = per_beat > 0.0 && to > from;\\n    let first = if ok { (from * per_beat).ceil() as i64 } else { 0 };\\n    let end = if ok { (to * per_beat).ceil() as i64 } else { 0 };\\n    (first..end).map(move |k| (k, k as f64 / per_beat))\\n}\\n\\nimpl Walk {\\n    /// step k\'s pitch (libm: the same bits native and wasm, as the built-in\'s)\\n    pub fn pitch_at(&self, seed: u64, k: i64) -> f32 {\\n        let r = unit(seed, k) as f32 * 2.0 - 1.0;\\n        self.base * math::pow(2.0, r * self.spread * self.octaves)\\n    }\\n}\\n\\nimpl Module for Walk {\\n    fn process(&mut self, block: &mut Block, ctx: &Ctx) {\\n        let tempo = ctx.tempo();\\n        let (from, to) = ctx.beats();\\n        let per_beat = f64::from(self.rate);\\n        let dur = f64::from(self.length) / per_beat.max(f64::MIN_POSITIVE);\\n        for (k, beat) in steps(from, to, per_beat) {\\n            // the step\'s frame in this block, rounded as the built-in\'s events are (deck-events `resolve`)\\n            let at = tempo.frame_of(beat).unwrap_or(ctx.frame());\\n            let frame = (at - ctx.frame()).max(0.0).round() as u32;\\n            let pitch = self.pitch_at(ctx.seed(), k);\\n            // the step is the note\'s id; the key is the host\'s to fill (a Hz source)\\n            let note = Ev::note_on(frame, k as u32, pitch, f32::NAN, 1.0).lasting(dur as f32).gliding(self.glide);\\n            block.emit(Self::NOTES, note);\\n        }\\n        let base = self.base;\\n        let cv = self.cv.get_or_insert_with(|| GateCv::new(base));\\n        let (mut out, notes) = block.audio_out_with_events(Self::CV, Self::NOTES);\\n        let (l, r) = out.stereo();\\n        cv.render_notes(&tempo, notes, l, r);\\n    }\\n}\\n"}}', UTC_TIMESTAMP(), 'migration:2026-11-05-factory-modules'),
  ('analog', 1, '{"id":"analog","name":"analog","factory":true,"files":{"adsr.rs":"//! The ADSR envelope. Attack is linear to 1; decay and release are exponential and take exactly their time: the level\\n//! has fallen to 0.1 % of the way\'s distance at the end (an analog RC\'s \\"time to 99.9 %\\"), then it is snapped to the\\n//! target. Times are read when a stage begins; the sustain level is live.\\nuse super::math::exp2;\\n\\n/// log2(0.001): the exponent that makes a decay of `n` samples end 0.1 % short of its target\\nconst LOG2_THOUSANDTH: f64 = -9.965_784_284_662_087;\\n\\n#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]\\npub enum Stage {\\n    #[default]\\n    Idle,\\n    Attack,\\n    Decay,\\n    Sustain,\\n    Release,\\n}\\n\\n/// A, D and R in seconds, S as a level 0..1\\n#[derive(Debug, Clone, Copy, PartialEq)]\\npub struct Times {\\n    pub attack: f32,\\n    pub decay: f32,\\n    pub sustain: f32,\\n    pub release: f32,\\n}\\n\\n#[derive(Debug, Clone, Copy, Default)]\\npub struct Adsr {\\n    stage: Stage,\\n    level: f32,\\n    /// samples into the stage and its length\\n    at: u32,\\n    len: u32,\\n    /// the exponential stages: the factor per sample; the attack: the step\\n    coef: f32,\\n    /// where the attack started (a retrigger rises from the level it found)\\n    from: f32,\\n}\\n\\nfn samples(seconds: f32, rate: f64) -> u32 {\\n    (f64::from(seconds.max(0.0)) * rate).round().max(1.0) as u32\\n}\\n\\nimpl Adsr {\\n    pub fn stage(&self) -> Stage {\\n        self.stage\\n    }\\n\\n    pub fn level(&self) -> f32 {\\n        self.level\\n    }\\n\\n    pub fn idle(&self) -> bool {\\n        self.stage == Stage::Idle\\n    }\\n\\n    /// the gate rises: attack from the current level\\n    pub fn gate_on(&mut self, t: &Times, rate: f64) {\\n        self.from = self.level;\\n        self.begin(Stage::Attack, samples(t.attack, rate), 0.0);\\n    }\\n\\n    /// the gate falls: release from the current level (nothing to do when idle)\\n    pub fn gate_off(&mut self, t: &Times, rate: f64) {\\n        if self.stage != Stage::Idle {\\n            self.release(t, rate);\\n        }\\n    }\\n\\n    fn release(&mut self, t: &Times, rate: f64) {\\n        let len = samples(t.release, rate);\\n        self.begin(Stage::Release, len, exp2(LOG2_THOUSANDTH / f64::from(len)) as f32);\\n    }\\n\\n    fn begin(&mut self, stage: Stage, len: u32, coef: f32) {\\n        self.stage = stage;\\n        self.at = 0;\\n        self.len = len;\\n        self.coef = coef;\\n    }\\n\\n    /// one sample; returns the level\\n    pub fn tick(&mut self, t: &Times, rate: f64) -> f32 {\\n        match self.stage {\\n            Stage::Idle => {}\\n            Stage::Attack => {\\n                self.at += 1;\\n                if self.at >= self.len {\\n                    self.level = 1.0;\\n                    let len = samples(t.decay, rate);\\n                    self.begin(Stage::Decay, len, exp2(LOG2_THOUSANDTH / f64::from(len)) as f32);\\n                } else {\\n                    self.level = self.from + (1.0 - self.from) * (self.at as f32 / self.len as f32);\\n                }\\n            }\\n            Stage::Decay => {\\n                self.at += 1;\\n                let s = t.sustain.clamp(0.0, 1.0);\\n                if self.at >= self.len {\\n                    self.level = s;\\n                    self.stage = Stage::Sustain;\\n                } else {\\n                    self.level = s + (self.level - s) * self.coef;\\n                }\\n            }\\n            Stage::Sustain => self.level = t.sustain.clamp(0.0, 1.0),\\n            Stage::Release => {\\n                self.at += 1;\\n                if self.at >= self.len {\\n                    self.level = 0.0;\\n                    self.stage = Stage::Idle;\\n                } else {\\n                    self.level *= self.coef;\\n                }\\n            }\\n        }\\n        self.level\\n    }\\n}\\n\\n#[cfg(test)]\\nmod tests {\\n    use super::*;\\n\\n    const RATE: f64 = 48_000.0;\\n    const T: Times = Times { attack: 0.01, decay: 0.2, sustain: 0.4, release: 0.5 };\\n\\n    /// run the envelope with the gate held for `held` samples, then released, and return every level\\n    fn run(t: &Times, held: usize, total: usize) -> Vec<f32> {\\n        let mut e = Adsr::default();\\n        e.gate_on(t, RATE);\\n        (0..total)\\n            .map(|i| {\\n                if i == held {\\n                    e.gate_off(t, RATE);\\n                }\\n                e.tick(t, RATE)\\n            })\\n            .collect()\\n    }\\n\\n    #[test]\\n    fn the_attack_takes_its_time_and_is_linear() {\\n        let x = run(&T, 100_000, 1000);\\n        let a = (T.attack as f64 * RATE).round() as usize; // 480\\n        assert!((x[a / 2 - 1] - 0.5).abs() < 0.01, \\"half-way through the attack: {}\\", x[a / 2 - 1]);\\n        assert!(x[a - 2] < 1.0 && x[a - 1] == 1.0, \\"peaks at sample {a}: {} {}\\", x[a - 2], x[a - 1]);\\n        assert!(x[..a].windows(2).all(|w| w[1] > w[0]));\\n    }\\n\\n    #[test]\\n    fn the_decay_ends_on_the_sustain_after_its_time() {\\n        let x = run(&T, 100_000, 20_000);\\n        let (a, d) = (480usize, 9600usize);\\n        // the decay\'s exponential: at its end only 0.1 % of the way is left\\n        let end = x[a + d - 2];\\n        assert!((end - T.sustain).abs() < 0.0012 * (1.0 - T.sustain) + 1e-4, \\"{end}\\");\\n        assert_eq!(x[a + d], T.sustain, \\"snapped to the sustain\\");\\n        assert!(x[a..a + d].windows(2).all(|w| w[1] <= w[0]), \\"falls monotonically\\");\\n        // half-way (in time) it is far from done: an exponential falls fast first\\n        assert!(x[a + d / 2] < T.sustain + 0.05 * (1.0 - T.sustain));\\n    }\\n\\n    #[test]\\n    fn the_sustain_holds_and_follows_the_knob() {\\n        let mut e = Adsr::default();\\n        e.gate_on(&T, RATE);\\n        for _ in 0..20_000 {\\n            e.tick(&T, RATE);\\n        }\\n        assert_eq!(e.stage(), Stage::Sustain);\\n        assert_eq!(e.level(), 0.4);\\n        let t2 = Times { sustain: 0.9, ..T };\\n        assert_eq!(e.tick(&t2, RATE), 0.9);\\n    }\\n\\n    #[test]\\n    fn the_release_falls_from_where_it_was_released_in_its_time() {\\n        let held = 20_000;\\n        let x = run(&T, held, held + 30_000);\\n        let r = (T.release as f64 * RATE) as usize; // 24000\\n        let start = x[held - 1];\\n        assert_eq!(start, 0.4);\\n        let end = x[held + r - 2];\\n        assert!((end / start - 0.001).abs() < 0.0001, \\"0.1 % left at the end: {}\\", end / start);\\n        assert_eq!(x[held + r - 1], 0.0, \\"silent and idle at the end of the release\\");\\n        assert_eq!(x[held + r + 100], 0.0);\\n        let mut e = Adsr::default();\\n        e.gate_on(&T, RATE);\\n        for _ in 0..held {\\n            e.tick(&T, RATE);\\n        }\\n        e.gate_off(&T, RATE);\\n        for _ in 0..r {\\n            assert!(!e.idle());\\n            e.tick(&T, RATE);\\n        }\\n        assert!(e.idle());\\n    }\\n\\n    #[test]\\n    fn releasing_during_the_attack_falls_from_the_level_reached() {\\n        let x = run(&T, 240, 2000); // half-way through the 480-sample attack\\n        let peak = x[239];\\n        assert!((peak - 0.5).abs() < 0.01);\\n        assert!(x[240] < peak && x[240] > peak * 0.99, \\"continues from {peak}: {}\\", x[240]);\\n        assert!(x[240..].windows(2).all(|w| w[1] <= w[0]));\\n    }\\n\\n    #[test]\\n    fn a_retrigger_rises_from_the_level_it_found() {\\n        let mut e = Adsr::default();\\n        e.gate_on(&T, RATE);\\n        for _ in 0..20_000 {\\n            e.tick(&T, RATE);\\n        }\\n        e.gate_on(&T, RATE);\\n        let first = e.tick(&T, RATE);\\n        assert!(first > 0.4 && first < 0.45, \\"no dip to zero: {first}\\");\\n    }\\n\\n    #[test]\\n    fn a_gate_off_while_idle_does_nothing() {\\n        let mut e = Adsr::default();\\n        e.gate_off(&T, RATE);\\n        assert!(e.idle() && e.tick(&T, RATE) == 0.0);\\n    }\\n}\\n","engine.rs":"//! The voice pool: eight voices, played by note events (module ABI v2, #343). A note on starts a note on a free voice – or\\n//! steals the oldest – keyed by the note\'s **id**, never by its pitch; its note off releases that voice, so a note\'s tail\\n//! keeps sounding on its own voice while the next notes start. A note on for an id that still sounds is a legato pitch\\n//! change of that voice; a bend (a per-note expression, semitones) moves the voice\'s pitch from the note\'s own; a reset\\n//! releases everything. The sustain control holds released notes while it is up. Events take effect at their frame: the\\n//! render cuts the block there, so a note lands on its sample however the host cuts the blocks.\\nuse crate::math::exp2;\\nuse crate::params::Patch;\\nuse crate::voice::{Note, Voice};\\nuse deck_module::{Ev, Expr, Kind, Tempo};\\n\\npub const VOICES: usize = 8;\\n\\n#[derive(Default)]\\npub struct Engine {\\n    voices: [Voice; VOICES],\\n    sustain: bool,\\n    next_age: u64,\\n    seed: u64,\\n    rate: f64,\\n}\\n\\nimpl Engine {\\n    pub fn init(&mut self, rate: f64, seed: u64) {\\n        *self = Engine { rate: rate.max(1.0), seed, ..Engine::default() };\\n    }\\n\\n    pub fn active_voices(&self) -> usize {\\n        self.voices.iter().filter(|v| v.active()).count()\\n    }\\n\\n    /// the voice the note `id` holds\\n    fn held(&self, id: u32) -> Option<usize> {\\n        self.voices.iter().position(|v| v.active() && v.id() == Some(id))\\n    }\\n\\n    fn note_on(&mut self, id: u32, hz: f32, vel: f32, p: &Patch) {\\n        if let Some(i) = self.held(id) {\\n            self.voices[i].set_pitch(hz);\\n            return;\\n        }\\n        let age = self.next_age;\\n        self.next_age += 1;\\n        let note = Note { hz, vel, id, age, seed: self.seed ^ age.wrapping_mul(0x9E37_79B9_7F4A_7C15) };\\n        match self.voices.iter().position(|v| !v.active()) {\\n            Some(i) => self.voices[i].start(note, p, self.rate),\\n            None => {\\n                let oldest = (0..VOICES).min_by_key(|&i| self.voices[i].age()).unwrap_or(0);\\n                self.voices[oldest].steal(note);\\n            }\\n        }\\n    }\\n\\n    fn note_off(&mut self, id: u32, p: &Patch) {\\n        if let Some(i) = self.held(id) {\\n            if self.sustain {\\n                self.voices[i].hold();\\n            } else {\\n                self.voices[i].release(p, self.rate);\\n            }\\n        }\\n    }\\n\\n    fn event(&mut self, e: &Ev, p: &Patch) {\\n        match e.kind() {\\n            Some(Kind::NoteOn) => {\\n                // the host fills Hz from a key and a missing velocity with 1; a note without a pitch is no note\\n                let (hz, vel) = (e.pitch_hz(), e.velocity());\\n                if hz.is_finite() && hz > 0.0 {\\n                    self.note_on(e.id, hz, if vel.is_finite() { vel.min(1.0) } else { 1.0 }, p);\\n                }\\n            }\\n            Some(Kind::NoteOff) => self.note_off(e.id, p),\\n            Some(Kind::NoteExpr) => {\\n                if let (Some((Expr::Bend, semis)), Some(i)) = (e.expr(), self.held(e.id)) {\\n                    if semis.is_finite() {\\n                        let base = self.voices[i].base();\\n                        self.voices[i].set_pitch((f64::from(base) * exp2(f64::from(semis) / 12.0)) as f32);\\n                    }\\n                }\\n            }\\n            Some(Kind::Reset) => {\\n                for i in 0..VOICES {\\n                    if self.voices[i].active() {\\n                        self.voices[i].release(p, self.rate);\\n                    }\\n                }\\n            }\\n            _ => {}\\n        }\\n    }\\n\\n    /// Render `out.0.len()` frames starting at audio frame `frame0` of the tempo map. `notes` are this call\'s note\\n    /// events (sorted by frame), `sustain` the pedal for this call.\\n    pub fn render(&mut self, p: &Patch, notes: &[Ev], sustain: bool, tempo: &Tempo, frame0: f64, out: (&mut [f32], &mut [f32])) {\\n        let (left, right) = out;\\n        if self.sustain && !sustain {\\n            for i in 0..VOICES {\\n                if self.voices[i].active() && self.voices[i].sustained() {\\n                    self.voices[i].release(p, self.rate);\\n                }\\n            }\\n        }\\n        self.sustain = sustain;\\n        let mut next = 0;\\n        for i in 0..left.len().min(right.len()) {\\n            while let Some(e) = notes.get(next).filter(|e| e.frame as usize <= i) {\\n                self.event(e, p);\\n                next += 1;\\n            }\\n            let beat = tempo.beat_at(frame0 + i as f64);\\n            let (mut l, mut r) = (0.0f32, 0.0f32);\\n            for v in self.voices.iter_mut().filter(|v| v.active()) {\\n                let (a, b) = v.render(p, self.rate, beat);\\n                l += a;\\n                r += b;\\n            }\\n            left[i] = l * p.volume;\\n            right[i] = r * p.volume;\\n        }\\n        // an event past the call\'s frames (a host never sends one) still counts, at its end\\n        for e in &notes[next.min(notes.len())..] {\\n            self.event(e, p);\\n        }\\n    }\\n}\\n","lfo.rs":"//! The LFO: five shapes, a free rate in Hz or locked to the tempo, a delay before it starts and an attack that fades it\\n//! in. Output −1..1. Free, it starts at phase 0 with the note; locked, its phase is the tempo\'s beat position (the\\n//! same on every voice and every deck that plays the same tempo map), sample & hold is seeded.\\nuse super::math::sin_turns;\\nuse super::noise::Noise;\\n\\n#[derive(Debug, Clone, Copy, PartialEq, Eq)]\\npub enum Shape {\\n    Sine,\\n    Tri,\\n    /// a rising ramp\\n    Saw,\\n    Square,\\n    SampleHold,\\n}\\n\\nimpl Shape {\\n    /// from a parameter value: 0 sine, 1 triangle, 2 saw, 3 square, 4 sample & hold\\n    pub fn from_param(v: f32) -> Shape {\\n        match v.round() as i32 {\\n            0 => Shape::Sine,\\n            1 => Shape::Tri,\\n            2 => Shape::Saw,\\n            3 => Shape::Square,\\n            _ => Shape::SampleHold,\\n        }\\n    }\\n}\\n\\n/// beats in one cycle for a sync setting: 0 off (free), then 2 bars, 1 bar, 1/2, 1/4 (a beat), 1/8, 1/16, 1/32 note\\npub const SYNC_BEATS: [f64; 8] = [0.0, 8.0, 4.0, 2.0, 1.0, 0.5, 0.25, 0.125];\\n\\npub fn beats_per_cycle(sync: f32) -> f64 {\\n    SYNC_BEATS[(sync.round() as usize).min(SYNC_BEATS.len() - 1)]\\n}\\n\\n/// One call\'s settings.\\n#[derive(Debug, Clone, Copy)]\\npub struct Settings {\\n    pub shape: Shape,\\n    pub rate_hz: f32,\\n    /// 0 = free; otherwise the beats in a cycle\\n    pub beats: f64,\\n    pub delay: f32,\\n    pub attack: f32,\\n}\\n\\n#[derive(Debug, Clone, Copy, Default)]\\npub struct Lfo {\\n    phase: f64,\\n    last: f64,\\n    held: f32,\\n    /// samples since the note began\\n    age: u64,\\n    noise: Noise,\\n}\\n\\nimpl Lfo {\\n    pub fn start(&mut self, seed: u64) {\\n        *self = Lfo { noise: Noise::new(seed), ..Lfo::default() };\\n        self.held = self.noise.next();\\n    }\\n\\n    /// One sample at the absolute `beat` of the tempo map.\\n    pub fn tick(&mut self, s: &Settings, rate: f64, beat: f64) -> f32 {\\n        let phase = if s.beats > 0.0 {\\n            let c = beat / s.beats;\\n            c - c.floor()\\n        } else {\\n            let p = self.phase;\\n            let next = p + f64::from(s.rate_hz) / rate;\\n            self.phase = next - next.floor();\\n            p\\n        };\\n        if phase < self.last {\\n            self.held = self.noise.next();\\n        }\\n        self.last = phase;\\n        let v = match s.shape {\\n            Shape::Sine => sin_turns(phase) as f32,\\n            Shape::Tri => {\\n                let u = phase + 0.25;\\n                (1.0 - 4.0 * (u - u.floor() - 0.5).abs()) as f32\\n            }\\n            Shape::Saw => (2.0 * phase - 1.0) as f32,\\n            Shape::Square => {\\n                if phase < 0.5 {\\n                    1.0\\n                } else {\\n                    -1.0\\n                }\\n            }\\n            Shape::SampleHold => self.held,\\n        };\\n        let delay = (f64::from(s.delay.max(0.0)) * rate) as u64;\\n        let fade = if self.age < delay {\\n            0.0\\n        } else if s.attack > 0.0 {\\n            (((self.age - delay) as f64 / (f64::from(s.attack) * rate)).min(1.0)) as f32\\n        } else {\\n            1.0\\n        };\\n        self.age += 1;\\n        v * fade\\n    }\\n}\\n\\n#[cfg(test)]\\nmod tests {\\n    use super::*;\\n\\n    const RATE: f64 = 48_000.0;\\n\\n    fn set(shape: Shape, hz: f32) -> Settings {\\n        Settings { shape, rate_hz: hz, beats: 0.0, delay: 0.0, attack: 0.0 }\\n    }\\n\\n    fn run(s: &Settings, n: usize) -> Vec<f32> {\\n        let mut l = Lfo::default();\\n        l.start(1);\\n        (0..n).map(|i| l.tick(s, RATE, i as f64 * 2.0 / RATE)).collect()\\n    }\\n\\n    #[test]\\n    fn every_shape_has_the_rate_it_is_set_to() {\\n        for shape in [Shape::Sine, Shape::Tri, Shape::Saw, Shape::Square] {\\n            let x = run(&set(shape, 5.0), 48_000);\\n            // the rising zero crossings (the square crosses at its step) are a period apart: 5 Hz = 9600 samples\\n            let up: Vec<usize> = (1..x.len()).filter(|&i| x[i - 1] < 0.0 && x[i] >= 0.0).collect();\\n            assert!(up.len() >= 4, \\"{shape:?}\\");\\n            assert!(up.windows(2).all(|w| w[1] - w[0] == 9600), \\"{shape:?}: {up:?}\\");\\n            assert!(x.iter().all(|v| v.abs() <= 1.0));\\n        }\\n    }\\n\\n    #[test]\\n    fn the_shapes_are_what_they_are_called() {\\n        let at = |shape, i| run(&set(shape, 1.0), 48_000)[i];\\n        assert!(at(Shape::Sine, 0).abs() < 1e-6 && (at(Shape::Sine, 12_000) - 1.0).abs() < 1e-6, \\"sine\\");\\n        assert!((at(Shape::Tri, 12_000) - 1.0).abs() < 1e-6 && (at(Shape::Tri, 36_000) + 1.0).abs() < 1e-6, \\"triangle\\");\\n        assert!((at(Shape::Saw, 0) + 1.0).abs() < 1e-6 && at(Shape::Saw, 47_999) > 0.999, \\"saw rises\\");\\n        assert_eq!((at(Shape::Square, 100), at(Shape::Square, 30_000)), (1.0, -1.0), \\"square\\");\\n    }\\n\\n    #[test]\\n    fn sample_and_hold_holds_a_new_seeded_value_each_cycle() {\\n        let x = run(&set(Shape::SampleHold, 10.0), 48_000);\\n        let mut values: Vec<f32> = x.clone();\\n        values.dedup();\\n        assert!(values.len() >= 9 && values.len() <= 11, \\"{} held values in 10 cycles\\", values.len());\\n        assert_eq!(x, run(&set(Shape::SampleHold, 10.0), 48_000), \\"the same seed holds the same values\\");\\n        let mut other = Lfo::default();\\n        other.start(2);\\n        assert_ne!(x[0], other.tick(&set(Shape::SampleHold, 10.0), RATE, 0.0));\\n    }\\n\\n    #[test]\\n    fn delay_and_attack_hold_and_fade_it_in() {\\n        let s = Settings { shape: Shape::Square, rate_hz: 1.0, beats: 0.0, delay: 0.5, attack: 0.25 };\\n        let x = run(&s, 48_000);\\n        assert!(x[..24_000].iter().all(|&v| v == 0.0), \\"silent through the delay\\");\\n        // after the delay it fades in over the attack: half-way through it, half strength (the square is still high)\\n        assert!((x[24_000 + 6_000].abs() - 0.5).abs() < 0.001, \\"{}\\", x[30_000]);\\n        assert_eq!(x[24_000 + 12_000].abs(), 1.0);\\n        assert!(x[24_000 + 11_999].abs() < 1.0, \\"just short of full\\");\\n    }\\n\\n    #[test]\\n    fn locked_to_the_tempo_it_follows_the_beat_not_the_note() {\\n        // one cycle a beat: 120 bpm = 2 beats a second = 2 Hz; the phase is the beat\'s fraction, whenever the note began\\n        let s = Settings { shape: Shape::Saw, rate_hz: 99.0, beats: 1.0, delay: 0.0, attack: 0.0 };\\n        let (mut a, mut b) = (Lfo::default(), Lfo::default());\\n        a.start(1);\\n        b.start(1);\\n        for i in 0..5000 {\\n            b.tick(&s, RATE, i as f64 / 24_000.0); // b has been running longer\\n        }\\n        for i in 0..100 {\\n            let beat = 1000.25 + i as f64 / 24_000.0;\\n            let (va, vb) = (a.tick(&s, RATE, beat), b.tick(&s, RATE, beat));\\n            assert!((va - vb).abs() < 1e-6, \\"same beat, same phase\\");\\n            assert!((f64::from(va) - (2.0 * (beat - beat.floor()) - 1.0)).abs() < 1e-5);\\n        }\\n        assert_eq!(beats_per_cycle(0.0), 0.0);\\n        assert_eq!(beats_per_cycle(4.0), 1.0);\\n        assert_eq!(beats_per_cycle(9.0), 0.125, \\"clamped to the last division\\");\\n    }\\n}\\n","lib.rs":"//! `analog` – a classic two-oscillator, two-filter, two-amp subtractive synth as one universal module (#331, README.md):\\n//! Osc 1 / Osc 2 (saw, pulse, triangle, sine; a sub each; Osc 2 hard-syncs to Osc 1) and noise → routing → Filter 1 /\\n//! Filter 2 (LP, BP, HP, notch; parallel or serial) → Amp 1 / Amp 2 (level, pan) → stereo out, modulated by two LFOs and\\n//! four ADSRs, eight voices. Notes come in on one event input (module ABI v2, #343: note on / off paired by id, with\\n//! velocity; a bend per note; a reset) and a sustain control; every control is a module parameter (`params.rs`, units and\\n//! docs in the descriptor); the factory preset `pad` is the descriptor\'s, the other presets are documents\\n//! (`analog.preset.json` holds three to import).\\n//!\\n//! Build: `cargo build --release --target wasm32-unknown-unknown -p analog-module` (the .wasm in\\n//! `target/wasm32-unknown-unknown/release/analog_module.wasm`).\\n// one `#[port(…)]` a port: clippy takes them for duplicates (deck/module/README.md)\\n#![allow(clippy::duplicated_attributes)]\\n// The synth\'s DSP units, plain Rust with no SDK in sight: band-limited oscillators, the state-variable filter, the ADSR,\\n// the LFO, the pan law and seeded noise. Nothing here allocates, reads a clock or calls the platform\'s maths: every\\n// transcendental is `math`\'s own arithmetic, so a render is bit-identical native ≡ wasm (ENGINE-REFACTOR-PLAN §3.4).\\n// Flat files beside lib.rs (#350): the build service takes a module as flat `src/*.rs` files only, so the catalog\'s\\n// `module:analog` stores exactly these. They are candidates to become deck-engine kinds later (#317 / #318).\\npub mod adsr;\\npub mod lfo;\\npub mod math;\\npub mod noise;\\npub mod osc;\\npub mod pan;\\npub mod svf;\\nmod engine;\\nmod params;\\nmod voice;\\n\\npub use engine::VOICES;\\npub use params::{Analog, Patch, PARAM_NAMES};\\n\\nuse deck_module::{Block, Ctx, Module};\\n\\nimpl Analog {\\n    /// how many voices sound (a tail counts)\\n    pub fn active_voices(&self) -> usize {\\n        self.engine.active_voices()\\n    }\\n}\\n\\nimpl Module for Analog {\\n    fn init(&mut self, ctx: &Ctx) {\\n        self.engine.init(ctx.rate(), ctx.seed());\\n    }\\n\\n    fn process(&mut self, block: &mut Block, ctx: &Ctx) {\\n        let patch = self.patch();\\n        let sustain = block.control_in(Self::SUSTAIN) >= 0.5;\\n        let notes = block.events_in(Self::NOTES);\\n        let mut out = block.audio_out(Self::OUT);\\n        let (left, right) = out.stereo();\\n        self.engine.render(&patch, notes, sustain, &ctx.tempo(), ctx.frame(), (left, right));\\n    }\\n}\\n","math.rs":"//! Maths from `+ − × ÷ floor` only – IEEE-exact and so identical on every target – instead of the platform\'s\\n//! `exp` / `sin` / `powf` / `tan` (ENGINE-REFACTOR-PLAN §3.4: native ≠ wasm there). Accuracy is far better than f32 needs.\\n\\npub const LN2: f64 = core::f64::consts::LN_2;\\n/// middle C in Hz: where key tracking is neutral\\npub const C4: f64 = 261.625_565_300_598_6;\\n\\n/// 2^x (x clamped to ±1000)\\npub fn exp2(x: f64) -> f64 {\\n    let x = x.clamp(-1000.0, 1000.0);\\n    let i = x.floor();\\n    let z = (x - i) * LN2; // e^z, z in [0, ln 2): the Taylor series to z^14\\n    let mut p = 1.0;\\n    let mut k = 14.0;\\n    while k >= 1.0 {\\n        p = 1.0 + p * z / k;\\n        k -= 1.0;\\n    }\\n    p * f64::from_bits(((i as i64 + 1023) as u64) << 52)\\n}\\n\\n/// log2(x) for x > 0 (anything else gives −1000)\\npub fn log2(x: f64) -> f64 {\\n    if x <= 1e-300 || !x.is_finite() {\\n        return -1000.0;\\n    }\\n    let bits = x.to_bits();\\n    let mut e = ((bits >> 52) & 0x7ff) as i64 - 1023;\\n    let mut m = f64::from_bits((bits & 0x000f_ffff_ffff_ffff) | (1023u64 << 52));\\n    if m > core::f64::consts::SQRT_2 {\\n        m *= 0.5;\\n        e += 1;\\n    }\\n    // ln m = 2 (s + s³/3 + s⁵/5 + …), s = (m − 1) / (m + 1), |s| < 0.172\\n    let s = (m - 1.0) / (m + 1.0);\\n    let s2 = s * s;\\n    let mut sum = 0.0;\\n    let mut k = 21.0;\\n    while k >= 1.0 {\\n        sum = 1.0 / k + s2 * sum;\\n        k -= 2.0;\\n    }\\n    e as f64 + 2.0 * s * sum / LN2\\n}\\n\\n/// sin(2π t), t in turns (any value; the fold keeps full precision)\\npub fn sin_turns(t: f64) -> f64 {\\n    let mut u = t - (t + 0.5).floor(); // [−0.5, 0.5)\\n    if u > 0.25 {\\n        u = 0.5 - u;\\n    } else if u < -0.25 {\\n        u = -0.5 - u;\\n    }\\n    let x = u * (2.0 * core::f64::consts::PI);\\n    let x2 = x * x;\\n    // x (1 − x²/6 (1 − x²/20 (1 − x²/42 (… x²/210)))): the Taylor series to x^15, error < 1e-11 at π/2\\n    let mut p = 1.0;\\n    let mut k = 15.0;\\n    while k >= 3.0 {\\n        p = 1.0 - p * x2 / (k * (k - 1.0));\\n        k -= 2.0;\\n    }\\n    x * p\\n}\\n\\n/// cos(2π t)\\npub fn cos_turns(t: f64) -> f64 {\\n    sin_turns(t + 0.25)\\n}\\n\\n/// tan(π x) for x in turns of the sample rate, 0 < x < 0.5 (the filter\'s prewarp)\\npub fn tan_pi(x: f64) -> f64 {\\n    sin_turns(x * 0.5) / cos_turns(x * 0.5)\\n}\\n\\n/// A soft clip with a rational curve: x (27 + x²) / (27 + 9x²), ±1 from |x| = 3 on (tanh\'s near twin, no exp).\\npub fn soft(x: f32) -> f32 {\\n    let x = x.clamp(-3.0, 3.0);\\n    x * (27.0 + x * x) / (27.0 + 9.0 * x * x)\\n}\\n\\n#[cfg(test)]\\nmod tests {\\n    use super::*;\\n\\n    #[test]\\n    fn exp2_matches_std() {\\n        let mut worst = 0.0f64;\\n        for i in -2000..=2000 {\\n            let x = i as f64 * 0.01;\\n            worst = worst.max(((exp2(x) - x.exp2()) / x.exp2()).abs());\\n        }\\n        assert!(worst < 1e-12, \\"{worst}\\");\\n        assert_eq!(exp2(0.0), 1.0);\\n        assert_eq!(exp2(3.0), 8.0);\\n        assert_eq!(exp2(-1.0), 0.5);\\n    }\\n\\n    #[test]\\n    fn log2_matches_std() {\\n        let mut worst = 0.0f64;\\n        let mut x = 1e-6;\\n        while x < 1e7 {\\n            worst = worst.max((log2(x) - x.log2()).abs());\\n            x *= 1.0137;\\n        }\\n        assert!(worst < 1e-12, \\"{worst}\\");\\n        assert_eq!(log2(1.0), 0.0);\\n        assert_eq!(log2(1024.0), 10.0);\\n        assert_eq!(log2(0.0), -1000.0);\\n    }\\n\\n    #[test]\\n    fn sin_and_tan_match_std() {\\n        let mut worst = 0.0f64;\\n        for i in -5000..=5000 {\\n            let t = i as f64 * 0.00137;\\n            worst = worst.max((sin_turns(t) - (t * core::f64::consts::TAU).sin()).abs());\\n            worst = worst.max((cos_turns(t) - (t * core::f64::consts::TAU).cos()).abs());\\n        }\\n        assert!(worst < 1e-10, \\"{worst}\\");\\n        for i in 1..450 {\\n            let x = i as f64 * 0.001;\\n            let want = (core::f64::consts::PI * x).tan();\\n            assert!(((tan_pi(x) - want) / want).abs() < 1e-9, \\"{x}\\");\\n        }\\n    }\\n\\n    #[test]\\n    fn soft_is_odd_bounded_and_linear_near_zero() {\\n        assert_eq!(soft(0.0), 0.0);\\n        assert_eq!(soft(5.0), 1.0);\\n        assert_eq!(soft(-5.0), -1.0);\\n        assert!((soft(0.01) - 0.01).abs() < 1e-6);\\n        assert_eq!(soft(0.7), -soft(-0.7));\\n    }\\n}\\n","noise.rs":"//! Seeded white noise: xorshift64*, uniform in [−1, 1). The seed is the module\'s (`Ctx::seed`) mixed with the note, so\\n//! two decks that play the same rig play the same noise; never a clock.\\n\\n#[derive(Debug, Clone, Copy)]\\npub struct Noise(u64);\\n\\nimpl Default for Noise {\\n    fn default() -> Self {\\n        Noise::new(0)\\n    }\\n}\\n\\n/// splitmix64\'s finaliser: one well-mixed 64-bit number from any input\\npub fn mix(x: u64) -> u64 {\\n    let mut z = x.wrapping_add(0x9E37_79B9_7F4A_7C15);\\n    z = (z ^ (z >> 30)).wrapping_mul(0xBF58_476D_1CE4_E5B9);\\n    z = (z ^ (z >> 27)).wrapping_mul(0x94D0_49BB_1331_11EB);\\n    z ^ (z >> 31)\\n}\\n\\nimpl Noise {\\n    pub fn new(seed: u64) -> Noise {\\n        Noise(mix(seed) | 1)\\n    }\\n\\n    #[allow(clippy::should_implement_trait)]\\n    pub fn next(&mut self) -> f32 {\\n        let mut x = self.0;\\n        x ^= x >> 12;\\n        x ^= x << 25;\\n        x ^= x >> 27;\\n        self.0 = x;\\n        let r = x.wrapping_mul(0x2545_F491_4F6C_DD1D);\\n        (r >> 40) as f32 * (1.0 / 8_388_608.0) - 1.0\\n    }\\n}\\n\\n#[cfg(test)]\\nmod tests {\\n    use super::*;\\n\\n    #[test]\\n    fn same_seed_same_noise_other_seed_other_noise() {\\n        let (mut a, mut b, mut c) = (Noise::new(5), Noise::new(5), Noise::new(6));\\n        let xs: Vec<f32> = (0..64).map(|_| a.next()).collect();\\n        assert!(xs.iter().all(|&x| x == b.next()));\\n        assert!(xs.iter().any(|&x| x != c.next()));\\n    }\\n\\n    #[test]\\n    fn is_white_uniform_and_bounded() {\\n        let mut n = Noise::new(1);\\n        let xs: Vec<f64> = (0..200_000).map(|_| n.next() as f64).collect();\\n        assert!(xs.iter().all(|&x| (-1.0..1.0).contains(&x)));\\n        let mean = xs.iter().sum::<f64>() / xs.len() as f64;\\n        let var = xs.iter().map(|x| (x - mean).powi(2)).sum::<f64>() / xs.len() as f64;\\n        assert!(mean.abs() < 0.01, \\"mean {mean}\\");\\n        assert!((var - 1.0 / 3.0).abs() < 0.01, \\"variance {var}\\");\\n        // white: neighbouring samples are uncorrelated\\n        let lag1 = xs.windows(2).map(|w| w[0] * w[1]).sum::<f64>() / (xs.len() - 1) as f64 / var;\\n        assert!(lag1.abs() < 0.01, \\"lag-1 correlation {lag1}\\");\\n    }\\n}\\n","osc.rs":"//! Band-limited oscillators: saw, pulse (with pulse width), triangle and sine; a square sub-oscillator one octave down;\\n//! hard sync. PolyBLEP (two samples) takes the aliasing out of the saw\'s and pulse\'s steps and, as PolyBLAMP, out of the\\n//! triangle\'s corners (ENGINE-REFACTOR-PLAN §3.1: PolyBLEP is cheap and plain; the wavetable is cleaner, see\\n//! ENGINE-ALIGNMENT §2a (d)).\\n//!\\n//! A step of height Δ at time x = 0 (x in samples, negative before it) is corrected by Δ/2 · B(x), B(x) = (1 + x)² for\\n//! x in [−1, 0) and −(1 − x)² for x in [0, 1). A kink whose slope changes by s a sample, by s · L(x) with L(x) =\\n//! (1 + x)³/6 before and (1 − x)³/6 after. A hard sync is a step that cannot be seen a sample ahead, so every\\n//! oscillator here **delays its output by one sample**: the half of the correction that belongs to the sample before the\\n//! event is added when that sample leaves.\\nuse super::math::sin_turns;\\n\\n#[derive(Debug, Clone, Copy, PartialEq, Eq)]\\npub enum Wave {\\n    Saw,\\n    Pulse,\\n    Tri,\\n    Sine,\\n}\\n\\nimpl Wave {\\n    /// from a parameter value: 0 saw, 1 pulse, 2 triangle, 3 sine\\n    pub fn from_param(v: f32) -> Wave {\\n        match v.round() as i32 {\\n            0 => Wave::Saw,\\n            1 => Wave::Pulse,\\n            2 => Wave::Tri,\\n            _ => Wave::Sine,\\n        }\\n    }\\n}\\n\\n/// the aliasing-free waveform at phase `t` (cycles): saw rises from −1, pulse is +1 until `pw`, triangle and sine start at\\n/// 0 going up\\nfn naive(wave: Wave, t: f64, pw: f64) -> f64 {\\n    match wave {\\n        Wave::Saw => 2.0 * t - 1.0,\\n        Wave::Pulse => {\\n            if t < pw {\\n                1.0\\n            } else {\\n                -1.0\\n            }\\n        }\\n        Wave::Tri => {\\n            let u = t + 0.25;\\n            1.0 - 4.0 * (u - u.floor() - 0.5).abs()\\n        }\\n        Wave::Sine => sin_turns(t),\\n    }\\n}\\n\\n/// the signed distance in cycles from the event at phase `c` to phase `p`, in (−0.5, 0.5]\\nfn dist(p: f64, c: f64) -> f64 {\\n    let d = p - c;\\n    d - (d + 0.5).floor()\\n}\\n\\nfn blep(x: f64) -> f64 {\\n    if (-1.0..0.0).contains(&x) {\\n        (1.0 + x) * (1.0 + x)\\n    } else if (0.0..1.0).contains(&x) {\\n        -(1.0 - x) * (1.0 - x)\\n    } else {\\n        0.0\\n    }\\n}\\n\\nfn blamp(x: f64) -> f64 {\\n    if (-1.0..0.0).contains(&x) {\\n        (1.0 + x) * (1.0 + x) * (1.0 + x) / 6.0\\n    } else if (0.0..1.0).contains(&x) {\\n        (1.0 - x) * (1.0 - x) * (1.0 - x) / 6.0\\n    } else {\\n        0.0\\n    }\\n}\\n\\n/// the correction for the waveform\'s own steps and kinks at phase `p`; `skip_wrap` leaves out the step at phase 0 (a\\n/// sync reset replaces it)\\nfn correction(wave: Wave, p: f64, dt: f64, pw: f64, skip_wrap: bool) -> f64 {\\n    let mut c = 0.0;\\n    match wave {\\n        Wave::Saw => {\\n            if !skip_wrap {\\n                c -= blep(dist(p, 0.0) / dt); // −2 / 2\\n            }\\n        }\\n        Wave::Pulse => {\\n            if !skip_wrap {\\n                c += blep(dist(p, 0.0) / dt); // +2 / 2\\n            }\\n            c -= blep(dist(p, pw) / dt);\\n        }\\n        Wave::Tri => {\\n            // slope 4 → −4 at a quarter, −4 → 4 at three quarters (per cycle): ±8 · dt a sample\\n            c -= 8.0 * dt * blamp(dist(p, 0.25) / dt);\\n            c += 8.0 * dt * blamp(dist(p, 0.75) / dt);\\n        }\\n        Wave::Sine => {}\\n    }\\n    c\\n}\\n\\n/// What one sample of an oscillator gives.\\n#[derive(Debug, Clone, Copy, PartialEq)]\\npub struct Tick {\\n    /// the output, one sample late\\n    pub value: f32,\\n    /// the phase wrapped (or was reset by a sync) during this sample, this fraction of a sample ago\\n    pub wrap: Option<f64>,\\n}\\n\\n#[derive(Debug, Clone, Copy, Default)]\\npub struct Osc {\\n    phase: f64,\\n    prev: f32,\\n}\\n\\nimpl Osc {\\n    pub fn reset(&mut self) {\\n        *self = Osc::default();\\n    }\\n\\n    /// One sample. `dt` = frequency / rate (cycles a sample), `pw` the pulse width, `reset` = a master oscillator\\n    /// wrapped this fraction of a sample ago and restarts this one (hard sync).\\n    pub fn tick(&mut self, wave: Wave, dt: f64, pw: f64, reset: Option<f64>) -> Tick {\\n        let dt = dt.clamp(1e-7, 0.45);\\n        let pw = pw.clamp(0.02, 0.98);\\n        let mut p = self.phase + dt;\\n        let mut wrap = None;\\n        let (mut jump, mut at) = (0.0, 0.0);\\n        if let Some(f) = reset {\\n            let before = p - dt * f; // the phase at the instant of the reset\\n            let before = before - before.floor();\\n            jump = naive(wave, 0.0, pw) - naive(wave, before, pw);\\n            at = f;\\n            p = dt * f;\\n            wrap = Some(f);\\n        } else if p >= 1.0 {\\n            p -= 1.0;\\n            wrap = Some(p / dt);\\n        }\\n        self.phase = p;\\n        let mut cur = naive(wave, p, pw) + correction(wave, p, dt, pw, reset.is_some());\\n        let mut pre = 0.0;\\n        if reset.is_some() {\\n            cur += jump * 0.5 * blep(at); // after the step\\n            pre = jump * 0.5 * blep(at - 1.0); // before it: belongs to the sample that has gone\\n        }\\n        let value = self.prev + pre as f32;\\n        self.prev = cur as f32;\\n        Tick { value, wrap }\\n    }\\n}\\n\\n/// A square one octave below its parent: a flip-flop that toggles on every wrap of the parent\'s phase (a sync reset\\n/// counts), so it is an exact octave and band-limited with the same PolyBLEP.\\n#[derive(Debug, Clone, Copy)]\\npub struct Sub {\\n    level: f64,\\n    prev: f32,\\n}\\n\\nimpl Default for Sub {\\n    fn default() -> Self {\\n        Sub { level: 1.0, prev: 1.0 }\\n    }\\n}\\n\\nimpl Sub {\\n    pub fn reset(&mut self) {\\n        *self = Sub::default();\\n    }\\n\\n    /// One sample; `wrap` is the parent\'s `Tick::wrap`. The output is one sample late like the parent\'s.\\n    pub fn tick(&mut self, wrap: Option<f64>) -> f32 {\\n        let (mut cur, mut pre) = (self.level, 0.0);\\n        if let Some(f) = wrap {\\n            self.level = -self.level;\\n            let jump = 2.0 * self.level;\\n            cur = self.level + jump * 0.5 * blep(f);\\n            pre = jump * 0.5 * blep(f - 1.0);\\n        }\\n        let value = self.prev + pre as f32;\\n        self.prev = cur as f32;\\n        value\\n    }\\n}\\n\\n#[cfg(test)]\\npub(crate) mod tests {\\n    use super::*;\\n\\n    const RATE: f64 = 48_000.0;\\n\\n    /// the magnitude spectrum of a power-of-two block (radix-2 FFT, no window: use it on coherent signals)\\n    pub fn spectrum(x: &[f32]) -> Vec<f64> {\\n        let n = x.len();\\n        let mut re: Vec<f64> = x.iter().map(|&v| f64::from(v)).collect();\\n        let mut im = vec![0.0f64; n];\\n        let mut j = 0;\\n        for i in 1..n {\\n            let mut bit = n >> 1;\\n            while j & bit != 0 {\\n                j ^= bit;\\n                bit >>= 1;\\n            }\\n            j ^= bit;\\n            if i < j {\\n                re.swap(i, j);\\n            }\\n        }\\n        let mut len = 2;\\n        while len <= n {\\n            let ang = -core::f64::consts::TAU / len as f64;\\n            for start in (0..n).step_by(len) {\\n                for k in 0..len / 2 {\\n                    let (wr, wi) = ((ang * k as f64).cos(), (ang * k as f64).sin());\\n                    let (a, b) = (start + k, start + k + len / 2);\\n                    let (tr, ti) = (re[b] * wr - im[b] * wi, re[b] * wi + im[b] * wr);\\n                    (re[b], im[b]) = (re[a] - tr, im[a] - ti);\\n                    (re[a], im[a]) = (re[a] + tr, im[a] + ti);\\n                }\\n            }\\n            len <<= 1;\\n        }\\n        (0..n / 2).map(|i| (re[i] * re[i] + im[i] * im[i]).sqrt() * 2.0 / n as f64).collect()\\n    }\\n\\n    fn render(wave: Wave, dt: f64, pw: f64, n: usize) -> Vec<f32> {\\n        let mut o = Osc::default();\\n        (0..n).map(|_| o.tick(wave, dt, pw, None).value).collect()\\n    }\\n\\n    /// harmonic amplitudes against 2/(π m), and the share of energy off the harmonics, for a saw whose period fits the\\n    /// block exactly (bin `k` of `n`)\\n    fn saw_purity(k: usize, n: usize, band_limited: bool) -> (Vec<f64>, f64) {\\n        let dt = k as f64 / n as f64;\\n        let x: Vec<f32> = if band_limited {\\n            render(Wave::Saw, dt, 0.5, n + 1)[1..].to_vec() // skip the one sample of delay: the block starts at the wrap\\n        } else {\\n            (0..n).map(|i| (2.0 * ((i as f64 * dt) % 1.0) - 1.0) as f32).collect()\\n        };\\n        let s = spectrum(&x);\\n        let harm: f64 = (1..).take_while(|m| m * k < n / 2).map(|m| s[m * k] * s[m * k]).sum();\\n        let off: f64 = (1..n / 2).filter(|b| b % k != 0).map(|b| s[b] * s[b]).sum();\\n        let amps = (1..=10).take_while(|m| m * k < n / 2).map(|m| s[m * k]).collect();\\n        (amps, 10.0 * (off / harm).log10())\\n    }\\n\\n    #[test]\\n    fn polyblep_saw_keeps_its_harmonics_and_loses_most_of_the_aliasing() {\\n        // 211 bins of 16384 at 48 kHz = 618 Hz; every alias lands off a harmonic bin (k is odd)\\n        let (amps, off_db) = saw_purity(211, 16384, true);\\n        let (_, naive_db) = saw_purity(211, 16384, false);\\n        for (i, a) in amps.iter().enumerate() {\\n            let m = (i + 1) as f64;\\n            let want = 2.0 / (core::f64::consts::PI * m);\\n            assert!((20.0 * (a / want).log10()).abs() < 0.6, \\"harmonic {m}: {a} against {want}\\");\\n        }\\n        assert!(off_db < -30.0, \\"off-harmonic energy {off_db} dB\\");\\n        assert!(off_db < naive_db - 15.0, \\"PolyBLEP {off_db} dB against the naive saw\'s {naive_db} dB\\");\\n    }\\n\\n    #[test]\\n    fn polyblep_stays_pure_high_up() {\\n        // 4.4 kHz: harmonics are few, the aliases of the 2nd and 3rd would sit right between them\\n        let (_, off_db) = saw_purity(1501, 16384, true);\\n        let (_, naive_db) = saw_purity(1501, 16384, false);\\n        assert!(off_db < -20.0 && off_db < naive_db - 8.0, \\"{off_db} dB against naive {naive_db} dB\\");\\n    }\\n\\n    #[test]\\n    fn pulse_width_sets_the_duty_cycle_and_the_dc() {\\n        for pw in [0.1, 0.25, 0.5, 0.8] {\\n            let n = 48_000;\\n            let x = render(Wave::Pulse, 100.0 / RATE, pw, n);\\n            let mean = x.iter().map(|&v| f64::from(v)).sum::<f64>() / n as f64;\\n            assert!((mean - (2.0 * pw - 1.0)).abs() < 0.002, \\"pw {pw}: mean {mean}\\");\\n            let high = x.iter().filter(|&&v| v > 0.0).count() as f64 / n as f64;\\n            assert!((high - pw).abs() < 0.002, \\"pw {pw}: duty {high}\\");\\n        }\\n    }\\n\\n    #[test]\\n    fn triangle_and_sine_have_unit_amplitude_and_the_right_period() {\\n        for wave in [Wave::Tri, Wave::Sine] {\\n            let x = render(wave, 1.0 / 128.0, 0.5, 1024);\\n            let peak = x.iter().fold(0.0f32, |m, v| m.max(v.abs()));\\n            assert!(peak > 0.98 && peak < 1.01, \\"{wave:?} peak {peak}\\");\\n            for i in 128..1024 - 128 {\\n                assert!((x[i] - x[i + 128]).abs() < 1e-5, \\"{wave:?} is not periodic at {i}\\");\\n            }\\n        }\\n    }\\n\\n    #[test]\\n    fn triangle_is_clean_where_the_naive_one_is_not() {\\n        // a triangle\'s harmonics fall as 1/m²: the odd ones have amplitude 8 / (π m)², the even ones none\\n        let (k, n) = (211usize, 16384usize);\\n        let x = render(Wave::Tri, k as f64 / n as f64, 0.5, n + 1)[1..].to_vec();\\n        let s = spectrum(&x);\\n        for m in [1usize, 3, 5, 7] {\\n            let want = 8.0 / (core::f64::consts::PI * m as f64).powi(2);\\n            assert!((20.0 * (s[m * k] / want).log10()).abs() < 0.3, \\"harmonic {m}: {} against {want}\\", s[m * k]);\\n        }\\n        let harm: f64 = (1..).take_while(|m| m * k < n / 2).map(|m| s[m * k] * s[m * k]).sum();\\n        let off: f64 = (1..n / 2).filter(|b| b % k != 0).map(|b| s[b] * s[b]).sum();\\n        assert!(10.0 * (off / harm).log10() < -60.0);\\n    }\\n\\n    #[test]\\n    fn sync_locks_osc2_to_the_period_of_osc1() {\\n        let (dt1, dt2) = (440.0 / RATE, 440.0 * 2.37 / RATE);\\n        let n = 48_000;\\n        let (mut o1, mut o2) = (Osc::default(), Osc::default());\\n        let (mut wraps, mut synced, mut free) = (vec![], vec![], vec![]);\\n        let mut o3 = Osc::default();\\n        for i in 0..n {\\n            let t1 = o1.tick(Wave::Saw, dt1, 0.5, None);\\n            if let Some(f) = t1.wrap {\\n                wraps.push(i as f64 - f);\\n            }\\n            synced.push(o2.tick(Wave::Saw, dt2, 0.5, t1.wrap).value);\\n            free.push(o3.tick(Wave::Saw, dt2, 0.5, None).value);\\n        }\\n        // and the pattern repeats with the master\'s period (48000 / 440 = 109.09… samples → every 6000 samples = 55 cycles)\\n        for i in 100..n - 6000 - 2 {\\n            assert!((synced[i] - synced[i + 6000]).abs() < 1e-3, \\"the synced saw is not periodic with the master at {i}\\");\\n        }\\n        // unsynced it is not: its own pitch runs against the master\'s\\n        let drift = (100..n - 6000 - 2).filter(|&i| (free[i] - free[i + 6000]).abs() > 0.1).count();\\n        assert!(drift > 10_000, \\"the free-running saw repeats too: {drift}\\");\\n        // the mean period of the master\'s wraps is its pitch\\n        let mean = (wraps[wraps.len() - 1] - wraps[0]) / (wraps.len() - 1) as f64;\\n        assert!((mean - RATE / 440.0).abs() < 0.01, \\"{mean}\\");\\n    }\\n\\n    #[test]\\n    fn sync_does_not_alias_much_more_than_a_plain_saw() {\\n        // a synced saw at 2.37× the master has steps of its own and the master\'s resets: all band-limited\\n        let (k1, n) = (97usize, 16384usize);\\n        let (dt1, dt2) = (k1 as f64 / n as f64, k1 as f64 * 2.37 / n as f64);\\n        let (mut o1, mut o2) = (Osc::default(), Osc::default());\\n        let x: Vec<f32> = (0..n + 1).map(|_| {\\n            let t = o1.tick(Wave::Saw, dt1, 0.5, None);\\n            o2.tick(Wave::Saw, dt2, 0.5, t.wrap).value\\n        }).collect();\\n        let s = spectrum(&x[1..]);\\n        let total: f64 = s.iter().map(|v| v * v).sum();\\n        // the signal repeats every master period, so its energy is on multiples of k1; what is off them is aliasing\\n        let off: f64 = (1..n / 2).filter(|b| b % k1 != 0).map(|b| s[b] * s[b]).sum();\\n        assert!(10.0 * (off / total).log10() < -28.0, \\"{} dB\\", 10.0 * (off / total).log10());\\n    }\\n\\n    #[test]\\n    fn the_sub_is_an_exact_octave_down_and_square() {\\n        let dt = 1000.0 / RATE;\\n        let (mut o, mut s) = (Osc::default(), Sub::default());\\n        let x: Vec<f32> = (0..48_000).map(|_| {\\n            let t = o.tick(Wave::Saw, dt, 0.5, None);\\n            s.tick(t.wrap)\\n        }).collect();\\n        // 500 Hz = 96 samples a period; sample the settled middle of each half\\n        let high = x.iter().filter(|&&v| v > 0.99).count() as f64;\\n        let low = x.iter().filter(|&&v| v < -0.99).count() as f64;\\n        assert!((high - low).abs() < 100.0 && high + low > 40_000.0, \\"square: {high} high {low} low\\");\\n        let crossings = (1..x.len()).filter(|&i| x[i - 1] < 0.0 && x[i] >= 0.0).count();\\n        assert!((499..=500).contains(&crossings), \\"500 Hz in a second = an octave under 1 kHz: {crossings} rising crossings\\");\\n    }\\n\\n    #[test]\\n    fn the_sub_follows_a_sync_reset() {\\n        // restarted by the master, the slave\'s wraps (reset or its own) toggle its sub: the sub still halves them\\n        let (mut o1, mut o2, mut s2) = (Osc::default(), Osc::default(), Sub::default());\\n        let mut wraps = 0;\\n        let x: Vec<f32> = (0..48_000).map(|_| {\\n            let t1 = o1.tick(Wave::Saw, 300.0 / RATE, 0.5, None);\\n            let t2 = o2.tick(Wave::Saw, 910.0 / RATE, 0.5, t1.wrap);\\n            wraps += usize::from(t2.wrap.is_some());\\n            s2.tick(t2.wrap)\\n        }).collect();\\n        let crossings = (1..x.len()).filter(|&i| x[i - 1] < 0.0 && x[i] >= 0.0).count();\\n        assert!(crossings.abs_diff(wraps / 2) <= 1, \\"{crossings} rising edges for {wraps} wraps\\");\\n    }\\n}\\n","pan.rs":"//! The pan law: constant power. Centre is −3 dB on each side, so a source keeps its loudness across the field.\\nuse super::math::{cos_turns, sin_turns};\\n\\n/// (left, right) gains for `pan` in −1 (left) … 1 (right): cos θ, sin θ with θ = (pan + 1) π/4\\npub fn gains(pan: f32) -> (f32, f32) {\\n    let t = (f64::from(pan.clamp(-1.0, 1.0)) + 1.0) * 0.125; // θ in turns\\n    (cos_turns(t) as f32, sin_turns(t) as f32)\\n}\\n\\n#[cfg(test)]\\nmod tests {\\n    use super::*;\\n\\n    #[test]\\n    fn power_is_constant_across_the_field() {\\n        for i in -100..=100 {\\n            let (l, r) = gains(i as f32 / 100.0);\\n            assert!((l * l + r * r - 1.0).abs() < 1e-6, \\"pan {i}: {l} {r}\\");\\n        }\\n    }\\n\\n    #[test]\\n    fn ends_and_centre() {\\n        let (l, r) = gains(-1.0);\\n        assert!((l - 1.0).abs() < 1e-6 && r.abs() < 1e-6);\\n        let (l, r) = gains(1.0);\\n        assert!(l.abs() < 1e-6 && (r - 1.0).abs() < 1e-6);\\n        let (l, r) = gains(0.0);\\n        assert!((l - core::f32::consts::FRAC_1_SQRT_2).abs() < 1e-6 && (r - l).abs() < 1e-7, \\"−3 dB each side\\");\\n        assert_eq!(gains(7.0), gains(1.0), \\"clamped\\");\\n    }\\n}\\n","params.rs":"//! The synth\'s parameters: ONE table – each row a `#[param]` attribute (range or choices, default, curve, unit, doc) the\\n//! derive reads into the descriptor (#343: the catalog descriptor carries units, choices and docs; no extra section) –\\n//! expanded into the module struct, the `Patch` snapshot the voices read and the name list. The factory preset `pad`\\n//! is the descriptor\'s one preset (`#[preset]`); every other preset is a document (research/ABI-V2.md §2).\\n//!\\n//! A switch or a mode is a number: 0 / 1, or 0..n with its `choices` in order (the value is the index). Names are at\\n//! most 24 lowercase characters.\\nuse crate::engine::Engine;\\nuse deck_module::Module;\\n\\nmacro_rules! analog {\\n    ( $( #[param($($meta:tt)*)] $name:ident; )* ) => {\\n        /// the synth: parameters (the table below), the voices behind them\\n        #[derive(Module)]\\n        #[module(name = \\"analog\\", doc = \\"a classic two-oscillator, two-filter, two-amp subtractive synth, eight voices\\")]\\n        #[port(input, event, name = \\"notes\\", names = \\"music.note\\", props = \\"pitch|vel|glide|key\\", capacity = 64, doc = \\"notes on and off (by id), a bend per note, a reset\\")]\\n        #[port(input, control, name = \\"sustain\\", doc = \\"the pedal: at 0.5 and above released notes hold\\")]\\n        #[port(output, audio, name = \\"out\\", channels = 2, doc = \\"stereo: the sum of the voices times volume\\")]\\n        #[preset(name = \\"pad\\", doc = \\"A wide, slow pad: a detuned saw through filter 1 on the left and a pulse with a slow pulse-width sweep through filter 2 on the right, a long filter bloom and a slow filter wobble.\\", values(volume = 0.6, o1_wave = 0.0, o1_fine = -7.0, o1_level = 0.7, o1_route = 0.0, o2_wave = 1.0, o2_fine = 7.0, o2_pw = 0.5, o2_level = 0.6, o2_route = 1.0, f1_cutoff = 1400.0, f1_res = 0.2, f1_key = 0.5, f1_env = 0.35, f2_cutoff = 2200.0, f2_res = 0.1, f2_key = 0.5, f2_env = 0.2, fe1_a = 1.2, fe1_d = 1.5, fe1_s = 0.5, fe1_r = 1.5, fe2_a = 1.5, fe2_d = 2.0, fe2_s = 0.6, fe2_r = 1.5, a1_level = 0.8, a1_pan = -0.55, a1_vel = 0.3, a2_level = 0.8, a2_pan = 0.55, a2_vel = 0.3, ae1_a = 0.9, ae1_d = 0.8, ae1_s = 0.85, ae1_r = 2.0, ae2_a = 1.1, ae2_d = 0.8, ae2_s = 0.85, ae2_r = 2.2, l1_shape = 0.0, l1_rate = 0.25, l1_f1 = 0.5, l2_shape = 1.0, l2_rate = 0.17, l2_pwm = 0.3, l2_f2 = 0.4))]\\n        pub struct Analog {\\n            $( #[param($($meta)*)] pub $name: f32, )*\\n            pub(crate) engine: Engine,\\n        }\\n\\n        /// every parameter\'s value at one moment: what the voices read\\n        #[derive(Debug, Clone, Copy)]\\n        pub struct Patch {\\n            $( pub $name: f32, )*\\n        }\\n\\n        impl Analog {\\n            pub fn patch(&self) -> Patch {\\n                Patch { $( $name: self.$name, )* }\\n            }\\n        }\\n\\n        /// the parameter names in descriptor order\\n        pub const PARAM_NAMES: &[&str] = &[$( stringify!($name), )*];\\n    };\\n}\\n\\nanalog! {\\n    #[param(range = 0.0..1.0, default = 0.7, doc = \\"master level: the sum of the voices times this\\")] volume;\\n\\n    #[param(choices = \\"saw|pulse|triangle|sine\\", default = 0, doc = \\"oscillator 1 waveform\\")] o1_wave;\\n    #[param(range = -24.0..24.0, default = 0.0, unit = \\"st\\", doc = \\"oscillator 1 pitch offset in semitones\\")] o1_semi;\\n    #[param(range = -100.0..100.0, default = 0.0, unit = \\"cent\\", doc = \\"oscillator 1 fine detune\\")] o1_fine;\\n    #[param(range = 0.05..0.95, default = 0.5, doc = \\"oscillator 1 pulse width (the pulse wave only)\\")] o1_pw;\\n    #[param(range = 0.0..1.0, default = 0.8, doc = \\"oscillator 1 level\\")] o1_level;\\n    #[param(range = 0.0..1.0, default = 0.0, doc = \\"oscillator 1 sub-oscillator level (a square, one octave down)\\")] o1_sub;\\n    #[param(range = 0.0..1.0, default = 1.0, doc = \\"oscillator 1 keyboard follow: 1 plays the pitch it is sent, 0 holds middle C\\")] o1_key;\\n\\n    #[param(choices = \\"saw|pulse|triangle|sine\\", default = 0, doc = \\"oscillator 2 waveform\\")] o2_wave;\\n    #[param(range = -24.0..24.0, default = 0.0, unit = \\"st\\", doc = \\"oscillator 2 pitch offset in semitones\\")] o2_semi;\\n    #[param(range = -100.0..100.0, default = 0.0, unit = \\"cent\\", doc = \\"oscillator 2 fine detune\\")] o2_fine;\\n    #[param(range = 0.05..0.95, default = 0.5, doc = \\"oscillator 2 pulse width (the pulse wave only)\\")] o2_pw;\\n    #[param(range = 0.0..1.0, default = 0.0, doc = \\"oscillator 2 level\\")] o2_level;\\n    #[param(range = 0.0..1.0, default = 0.0, doc = \\"oscillator 2 sub-oscillator level (a square, one octave down)\\")] o2_sub;\\n    #[param(range = 0.0..1.0, default = 1.0, doc = \\"oscillator 2 keyboard follow: 1 plays the pitch it is sent, 0 holds middle C\\")] o2_key;\\n    #[param(choices = \\"off|on\\", default = 0, doc = \\"hard sync: oscillator 1 restarts oscillator 2 at every cycle\\")] o2_sync;\\n\\n    #[param(range = 0.0..1.0, default = 0.0, doc = \\"white noise level (seeded, the same on every deck)\\")] noise_level;\\n\\n    #[param(choices = \\"filter 1|filter 2|both\\", default = 0, doc = \\"where oscillator 1 goes\\")] o1_route;\\n    #[param(choices = \\"filter 1|filter 2|both\\", default = 0, doc = \\"where oscillator 1\'s sub goes\\")] sub1_route;\\n    #[param(choices = \\"filter 1|filter 2|both\\", default = 0, doc = \\"where oscillator 2 goes\\")] o2_route;\\n    #[param(choices = \\"filter 1|filter 2|both\\", default = 0, doc = \\"where oscillator 2\'s sub goes\\")] sub2_route;\\n    #[param(choices = \\"filter 1|filter 2|both\\", default = 0, doc = \\"where the noise goes\\")] noise_route;\\n    #[param(choices = \\"parallel|serial\\", default = 0, doc = \\"serial: filter 1\'s output also feeds filter 2\\")] f_serial;\\n    #[param(range = 0.0..1.0, default = 1.0, doc = \\"how much of filter 1 feeds filter 2 (serial only)\\")] f1_to_f2;\\n\\n    #[param(range = -12.0..12.0, default = 0.0, unit = \\"st\\", doc = \\"velocity to pitch: semitones at full velocity\\")] vel_pitch;\\n    #[param(range = -0.45..0.45, default = 0.0, doc = \\"velocity to pulse width of both oscillators at full velocity\\")] vel_pwm;\\n\\n    #[param(choices = \\"lowpass|bandpass|highpass|notch\\", default = 0, doc = \\"filter 1 type\\")] f1_mode;\\n    #[param(range = 20.0..20000.0, default = 8000.0, curve = log, unit = \\"Hz\\", doc = \\"filter 1 cutoff\\")] f1_cutoff;\\n    #[param(range = 0.0..1.0, default = 0.0, doc = \\"filter 1 resonance\\")] f1_res;\\n    #[param(range = 0.0..1.0, default = 0.0, doc = \\"filter 1 drive: saturation in front of the filter\\")] f1_drive;\\n    #[param(range = -1.0..1.0, default = 0.0, doc = \\"filter 1 key tracking: 1 moves the cutoff an octave per octave of pitch\\")] f1_key;\\n    #[param(range = -1.0..1.0, default = 0.0, doc = \\"filter 1 envelope amount: six octaves at full\\")] f1_env;\\n    #[param(range = 0.0..1.0, default = 0.0, doc = \\"velocity to filter 1 cutoff: four octaves at full velocity\\")] f1_vel;\\n    #[param(range = 0.0..1.0, default = 0.0, doc = \\"velocity to filter 1 resonance\\")] f1_velres;\\n\\n    #[param(choices = \\"lowpass|bandpass|highpass|notch\\", default = 0, doc = \\"filter 2 type\\")] f2_mode;\\n    #[param(range = 20.0..20000.0, default = 8000.0, curve = log, unit = \\"Hz\\", doc = \\"filter 2 cutoff\\")] f2_cutoff;\\n    #[param(range = 0.0..1.0, default = 0.0, doc = \\"filter 2 resonance\\")] f2_res;\\n    #[param(range = 0.0..1.0, default = 0.0, doc = \\"filter 2 drive: saturation in front of the filter\\")] f2_drive;\\n    #[param(range = -1.0..1.0, default = 0.0, doc = \\"filter 2 key tracking: 1 moves the cutoff an octave per octave of pitch\\")] f2_key;\\n    #[param(range = -1.0..1.0, default = 0.0, doc = \\"filter 2 envelope amount: six octaves at full\\")] f2_env;\\n    #[param(range = 0.0..1.0, default = 0.0, doc = \\"velocity to filter 2 cutoff: four octaves at full velocity\\")] f2_vel;\\n    #[param(range = 0.0..1.0, default = 0.0, doc = \\"velocity to filter 2 resonance\\")] f2_velres;\\n\\n    #[param(range = 0.001..10.0, default = 0.005, unit = \\"s\\", doc = \\"filter envelope 1 attack\\")] fe1_a;\\n    #[param(range = 0.001..10.0, default = 0.3, unit = \\"s\\", doc = \\"filter envelope 1 decay\\")] fe1_d;\\n    #[param(range = 0.0..1.0, default = 0.5, doc = \\"filter envelope 1 sustain level\\")] fe1_s;\\n    #[param(range = 0.001..10.0, default = 0.3, unit = \\"s\\", doc = \\"filter envelope 1 release\\")] fe1_r;\\n    #[param(range = 0.001..10.0, default = 0.005, unit = \\"s\\", doc = \\"filter envelope 2 attack\\")] fe2_a;\\n    #[param(range = 0.001..10.0, default = 0.3, unit = \\"s\\", doc = \\"filter envelope 2 decay\\")] fe2_d;\\n    #[param(range = 0.0..1.0, default = 0.5, doc = \\"filter envelope 2 sustain level\\")] fe2_s;\\n    #[param(range = 0.001..10.0, default = 0.3, unit = \\"s\\", doc = \\"filter envelope 2 release\\")] fe2_r;\\n    #[param(range = -24.0..24.0, default = 0.0, unit = \\"st\\", doc = \\"filter envelope 2 to oscillator 2 pitch only: semitones at full (the classic sync sweep)\\")] fe2_p2;\\n\\n    #[param(range = 0.0..1.0, default = 0.8, doc = \\"amp 1 level (filter 1\'s output)\\")] a1_level;\\n    #[param(range = -1.0..1.0, default = 0.0, doc = \\"amp 1 pan, constant power\\")] a1_pan;\\n    #[param(range = 0.0..1.0, default = 0.5, doc = \\"velocity to amp 1 level\\")] a1_vel;\\n    #[param(range = -1.0..1.0, default = 0.0, doc = \\"amp 1 key tracking: level change with pitch, 3 dB an octave at full\\")] a1_key;\\n    #[param(range = 0.0..1.0, default = 0.8, doc = \\"amp 2 level (filter 2\'s output)\\")] a2_level;\\n    #[param(range = -1.0..1.0, default = 0.0, doc = \\"amp 2 pan, constant power\\")] a2_pan;\\n    #[param(range = 0.0..1.0, default = 0.5, doc = \\"velocity to amp 2 level\\")] a2_vel;\\n    #[param(range = -1.0..1.0, default = 0.0, doc = \\"amp 2 key tracking: level change with pitch, 3 dB an octave at full\\")] a2_key;\\n\\n    #[param(range = 0.001..10.0, default = 0.003, unit = \\"s\\", doc = \\"amp envelope 1 attack\\")] ae1_a;\\n    #[param(range = 0.001..10.0, default = 0.3, unit = \\"s\\", doc = \\"amp envelope 1 decay\\")] ae1_d;\\n    #[param(range = 0.0..1.0, default = 0.8, doc = \\"amp envelope 1 sustain level\\")] ae1_s;\\n    #[param(range = 0.001..10.0, default = 0.25, unit = \\"s\\", doc = \\"amp envelope 1 release\\")] ae1_r;\\n    #[param(range = 0.001..10.0, default = 0.003, unit = \\"s\\", doc = \\"amp envelope 2 attack\\")] ae2_a;\\n    #[param(range = 0.001..10.0, default = 0.3, unit = \\"s\\", doc = \\"amp envelope 2 decay\\")] ae2_d;\\n    #[param(range = 0.0..1.0, default = 0.8, doc = \\"amp envelope 2 sustain level\\")] ae2_s;\\n    #[param(range = 0.001..10.0, default = 0.25, unit = \\"s\\", doc = \\"amp envelope 2 release\\")] ae2_r;\\n\\n    #[param(choices = \\"sine|triangle|saw|square|sample & hold\\", default = 0, doc = \\"LFO 1 shape\\")] l1_shape;\\n    #[param(range = 0.01..40.0, default = 4.0, curve = log, unit = \\"Hz\\", doc = \\"LFO 1 rate when free-running\\")] l1_rate;\\n    #[param(choices = \\"free|2 bars|1 bar|1/2|1/4|1/8|1/16|1/32\\", default = 0, doc = \\"LFO 1 tempo sync: a cycle per note value, locked to the beat\\")] l1_sync;\\n    #[param(range = 0.0..5.0, default = 0.0, unit = \\"s\\", doc = \\"LFO 1 delay: silent for this long after the note starts\\")] l1_delay;\\n    #[param(range = 0.0..5.0, default = 0.0, unit = \\"s\\", doc = \\"LFO 1 attack: fades in over this long after the delay\\")] l1_attack;\\n    #[param(range = 0.0..12.0, default = 0.0, unit = \\"st\\", doc = \\"LFO 1 to pitch of both oscillators: semitones either way (vibrato)\\")] l1_pitch;\\n    #[param(range = 0.0..0.45, default = 0.0, doc = \\"LFO 1 to the pulse width of both oscillators\\")] l1_pwm;\\n    #[param(range = 0.0..4.0, default = 0.0, unit = \\"oct\\", doc = \\"LFO 1 to filter 1 cutoff: octaves either way\\")] l1_f1;\\n    #[param(range = 0.0..4.0, default = 0.0, unit = \\"oct\\", doc = \\"LFO 1 to filter 2 cutoff: octaves either way\\")] l1_f2;\\n    #[param(range = 0.0..1.0, default = 0.0, doc = \\"LFO 1 to amp 1 level (tremolo depth)\\")] l1_a1;\\n    #[param(range = 0.0..1.0, default = 0.0, doc = \\"LFO 1 to amp 2 level (tremolo depth)\\")] l1_a2;\\n    #[param(range = 0.0..12.0, default = 0.0, unit = \\"st\\", doc = \\"LFO 1 to oscillator 2 pitch only: semitones either way (sweeps a synced oscillator)\\")] l1_p2;\\n\\n    #[param(choices = \\"sine|triangle|saw|square|sample & hold\\", default = 0, doc = \\"LFO 2 shape\\")] l2_shape;\\n    #[param(range = 0.01..40.0, default = 4.0, curve = log, unit = \\"Hz\\", doc = \\"LFO 2 rate when free-running\\")] l2_rate;\\n    #[param(choices = \\"free|2 bars|1 bar|1/2|1/4|1/8|1/16|1/32\\", default = 0, doc = \\"LFO 2 tempo sync: a cycle per note value, locked to the beat\\")] l2_sync;\\n    #[param(range = 0.0..5.0, default = 0.0, unit = \\"s\\", doc = \\"LFO 2 delay: silent for this long after the note starts\\")] l2_delay;\\n    #[param(range = 0.0..5.0, default = 0.0, unit = \\"s\\", doc = \\"LFO 2 attack: fades in over this long after the delay\\")] l2_attack;\\n    #[param(range = 0.0..12.0, default = 0.0, unit = \\"st\\", doc = \\"LFO 2 to pitch of both oscillators: semitones either way (vibrato)\\")] l2_pitch;\\n    #[param(range = 0.0..0.45, default = 0.0, doc = \\"LFO 2 to the pulse width of both oscillators\\")] l2_pwm;\\n    #[param(range = 0.0..4.0, default = 0.0, unit = \\"oct\\", doc = \\"LFO 2 to filter 1 cutoff: octaves either way\\")] l2_f1;\\n    #[param(range = 0.0..4.0, default = 0.0, unit = \\"oct\\", doc = \\"LFO 2 to filter 2 cutoff: octaves either way\\")] l2_f2;\\n    #[param(range = 0.0..1.0, default = 0.0, doc = \\"LFO 2 to amp 1 level (tremolo depth)\\")] l2_a1;\\n    #[param(range = 0.0..1.0, default = 0.0, doc = \\"LFO 2 to amp 2 level (tremolo depth)\\")] l2_a2;\\n    #[param(range = 0.0..12.0, default = 0.0, unit = \\"st\\", doc = \\"LFO 2 to oscillator 2 pitch only: semitones either way (sweeps a synced oscillator)\\")] l2_p2;\\n}\\n","svf.rs":"//! The state-variable filter (a trapezoidal / zero-delay-feedback SVF): low-pass, band-pass, high-pass and notch from\\n//! one pair of integrators, stable under fast cutoff modulation, with resonance up to self-oscillation\'s edge and a\\n//! drive stage in front.\\nuse super::math::{exp2, soft, tan_pi};\\n\\n#[derive(Debug, Clone, Copy, PartialEq, Eq)]\\npub enum Mode {\\n    Lp,\\n    Bp,\\n    Hp,\\n    Notch,\\n}\\n\\nimpl Mode {\\n    /// from a parameter value: 0 low-pass, 1 band-pass, 2 high-pass, 3 notch\\n    pub fn from_param(v: f32) -> Mode {\\n        match v.round() as i32 {\\n            0 => Mode::Lp,\\n            1 => Mode::Bp,\\n            2 => Mode::Hp,\\n            _ => Mode::Notch,\\n        }\\n    }\\n}\\n\\n/// damping k = 1/Q for a resonance 0..1: Q 0.707 at 0, about 24 at 1 (exponential, so the knob feels even)\\npub fn damping(res: f32) -> f64 {\\n    core::f64::consts::SQRT_2 * exp2(-5.1 * f64::from(res.clamp(0.0, 1.0)))\\n}\\n\\n/// The coefficients for one cutoff and resonance; recomputed at control rate, not per sample.\\n#[derive(Debug, Clone, Copy, Default)]\\npub struct Coef {\\n    a1: f32,\\n    a2: f32,\\n    a3: f32,\\n    k: f32,\\n}\\n\\nimpl Coef {\\n    /// `cutoff` in Hz (kept between 10 Hz and 0.45 of the rate), `res` 0..1\\n    pub fn new(cutoff: f64, res: f32, rate: f64) -> Coef {\\n        let fc = cutoff.clamp(10.0, 0.45 * rate);\\n        let g = tan_pi(fc / rate);\\n        let k = damping(res);\\n        let a1 = 1.0 / (1.0 + g * (g + k));\\n        Coef { a1: a1 as f32, a2: (g * a1) as f32, a3: (g * g * a1) as f32, k: k as f32 }\\n    }\\n}\\n\\n#[derive(Debug, Clone, Copy, Default)]\\npub struct Svf {\\n    ic1: f32,\\n    ic2: f32,\\n}\\n\\nimpl Svf {\\n    pub fn reset(&mut self) {\\n        *self = Svf::default();\\n    }\\n\\n    pub fn tick(&mut self, c: &Coef, mode: Mode, x: f32) -> f32 {\\n        let v3 = x - self.ic2;\\n        let v1 = c.a1 * self.ic1 + c.a2 * v3;\\n        let v2 = self.ic2 + c.a2 * self.ic1 + c.a3 * v3;\\n        self.ic1 = 2.0 * v1 - self.ic1;\\n        self.ic2 = 2.0 * v2 - self.ic2;\\n        match mode {\\n            Mode::Lp => v2,\\n            Mode::Bp => v1,\\n            Mode::Hp => x - c.k * v1 - v2,\\n            Mode::Notch => x - c.k * v1,\\n        }\\n    }\\n}\\n\\n/// The drive stage: 0 passes the signal untouched, 1 pushes it ten times harder into a soft clip (ceiling ±1); in\\n/// between it is a crossfade between the two, so the knob has no step at 0.\\npub fn drive(x: f32, amount: f32) -> f32 {\\n    if amount <= 0.0 {\\n        return x;\\n    }\\n    let a = amount.min(1.0);\\n    let gain = 1.0 + 9.0 * a;\\n    x + a * (soft(x * gain) - x)\\n}\\n\\n#[cfg(test)]\\nmod tests {\\n    use super::*;\\n\\n    const RATE: f64 = 48_000.0;\\n\\n    /// the steady-state gain (linear) at `f` Hz for a filter at `fc` / `res`\\n    fn gain(mode: Mode, fc: f64, res: f32, f: f64) -> f64 {\\n        let c = Coef::new(fc, res, RATE);\\n        let mut s = Svf::default();\\n        let n = 48_000;\\n        let mut sum = 0.0f64;\\n        for i in 0..n {\\n            let x = (core::f64::consts::TAU * f * i as f64 / RATE).sin() as f32;\\n            let y = s.tick(&c, mode, x);\\n            if i >= n / 2 {\\n                sum += f64::from(y) * f64::from(y);\\n            }\\n        }\\n        (2.0 * sum / (n / 2) as f64).sqrt() // the amplitude, from the rms: a sample grid can miss the peak\\n    }\\n\\n    /// the bilinear-transformed 2nd-order prototype: Ω = tan(π f / fs) / tan(π fc / fs)\\n    fn expected(mode: Mode, fc: f64, res: f32, f: f64) -> f64 {\\n        let w = (core::f64::consts::PI * f / RATE).tan() / (core::f64::consts::PI * fc / RATE).tan();\\n        let k = damping(res);\\n        let den = ((1.0 - w * w).powi(2) + (k * w).powi(2)).sqrt();\\n        match mode {\\n            Mode::Lp => 1.0 / den,\\n            Mode::Bp => w / den,\\n            Mode::Hp => w * w / den,\\n            Mode::Notch => (1.0 - w * w).abs() / den,\\n        }\\n    }\\n\\n    #[test]\\n    fn all_four_modes_follow_their_analytic_response() {\\n        for (mode, res) in [(Mode::Lp, 0.0), (Mode::Lp, 0.5), (Mode::Bp, 0.3), (Mode::Hp, 0.0), (Mode::Hp, 0.6), (Mode::Notch, 0.2)] {\\n            for f in [100.0, 500.0, 1000.0, 2000.0, 8000.0] {\\n                let (got, want) = (gain(mode, 1000.0, res, f), expected(mode, 1000.0, res, f));\\n                let db = 20.0 * (got / want).log10();\\n                // a notch is a point of zero: judge it by the difference, not the ratio\\n                let ok = if mode == Mode::Notch && want < 0.02 { (got - want).abs() < 0.01 } else { db.abs() < 0.1 };\\n                assert!(ok, \\"{mode:?} res {res} at {f} Hz: got {got:.4}, want {want:.4} ({db:.2} dB)\\");\\n            }\\n        }\\n    }\\n\\n    #[test]\\n    fn the_modes_have_the_shapes_they_are_named_for() {\\n        let at = |m: Mode, f: f64| gain(m, 1000.0, 0.0, f);\\n        // low-pass: through below the cutoff, −3 dB at it (Q 0.707), 12 dB an octave above (2nd order)\\n        assert!((at(Mode::Lp, 50.0) - 1.0).abs() < 0.01);\\n        assert!((at(Mode::Lp, 1000.0) - core::f64::consts::FRAC_1_SQRT_2).abs() < 0.01);\\n        assert!(at(Mode::Lp, 8000.0) < 0.02);\\n        // high-pass: the mirror image\\n        assert!(at(Mode::Hp, 50.0) < 0.01);\\n        assert!((at(Mode::Hp, 1000.0) - core::f64::consts::FRAC_1_SQRT_2).abs() < 0.01);\\n        assert!((at(Mode::Hp, 15000.0) - 1.0).abs() < 0.05);\\n        // band-pass: peaks at the cutoff, with gain 1/k there, and falls away on both sides\\n        let k = damping(0.0);\\n        assert!((at(Mode::Bp, 1000.0) - 1.0 / k).abs() < 0.02);\\n        assert!(at(Mode::Bp, 100.0) < 0.2 * at(Mode::Bp, 1000.0) && at(Mode::Bp, 10000.0) < 0.2 * at(Mode::Bp, 1000.0));\\n        // notch: through at both ends, a hole at the cutoff\\n        assert!((at(Mode::Notch, 50.0) - 1.0).abs() < 0.01 && (at(Mode::Notch, 15000.0) - 1.0).abs() < 0.05);\\n        assert!(at(Mode::Notch, 1000.0) < 0.01);\\n    }\\n\\n    #[test]\\n    fn resonance_raises_the_peak_at_the_cutoff() {\\n        let peaks: Vec<f64> = [0.0, 0.3, 0.6, 0.9].iter().map(|&r| gain(Mode::Lp, 1000.0, r, 1000.0)).collect();\\n        assert!(peaks.windows(2).all(|w| w[1] > w[0] * 1.3), \\"{peaks:?}\\");\\n        assert!(peaks[3] > 8.0, \\"high resonance is a real peak: {peaks:?}\\");\\n    }\\n\\n    #[test]\\n    fn a_cutoff_swept_hard_stays_finite_and_bounded() {\\n        let mut s = Svf::default();\\n        let mut peak = 0.0f32;\\n        for i in 0..96_000 {\\n            let fc = 20.0 * 1000f64.powf((i % 4800) as f64 / 4800.0); // saw sweep 20 Hz … 20 kHz\\n            let c = Coef::new(fc, 0.95, RATE);\\n            let x = if i % 200 < 100 { 1.0 } else { -1.0 };\\n            let y = s.tick(&c, Mode::Lp, x);\\n            assert!(y.is_finite());\\n            peak = peak.max(y.abs());\\n        }\\n        assert!(peak < 60.0, \\"{peak}\\");\\n    }\\n\\n    #[test]\\n    fn drive_is_a_bypass_at_zero_and_saturates_above() {\\n        assert_eq!(drive(0.8, 0.0), 0.8);\\n        let loud = drive(4.0, 1.0);\\n        assert!(loud.abs() <= 2.0 && loud > 0.5, \\"{loud}\\");\\n        assert!(drive(0.5, 0.01) > 0.49 && drive(0.5, 0.01) < 0.51, \\"continuous at 0\\");\\n        assert_eq!(drive(0.3, 0.7), -drive(-0.3, 0.7));\\n    }\\n}\\n","voice.rs":"//! One voice: the whole chain of the schema – Osc 1 / Osc 2 (+ their subs) / noise → routing → Filter 1 / Filter 2 →\\n//! Amp 1 / Amp 2 → stereo – with its two LFOs and four envelopes. Modulation is read every sample; what is costly (the\\n//! pitch, the cutoffs, the pan) is recomputed every `CTRL` samples of the voice\'s own clock, so a render does not\\n//! depend on how the host cut the audio into blocks.\\nuse crate::adsr::{Adsr, Times};\\nuse crate::lfo::{self, Lfo, Settings as LfoSettings, Shape};\\nuse crate::math::{exp2, log2, C4};\\nuse crate::noise::{mix, Noise};\\nuse crate::osc::{Osc, Sub, Wave};\\nuse crate::pan;\\nuse crate::svf::{self, Coef, Mode, Svf};\\nuse crate::params::Patch;\\n\\n/// samples between the control-rate updates (0.33 ms at 48 kHz)\\npub const CTRL: u32 = 16;\\n/// samples a stolen voice takes to fade out before the new note starts (1 ms)\\npub const FADE: u32 = 48;\\n\\n/// a note on its way into a voice\\n#[derive(Debug, Clone, Copy)]\\npub struct Note {\\n    pub hz: f32,\\n    pub vel: f32,\\n    /// the note event\'s id: its note off and bends find the voice by it\\n    pub id: u32,\\n    /// the note counter: smaller = older\\n    pub age: u64,\\n    pub seed: u64,\\n}\\n\\nfn fe_times(p: &Patch, n: usize) -> Times {\\n    if n == 0 {\\n        Times { attack: p.fe1_a, decay: p.fe1_d, sustain: p.fe1_s, release: p.fe1_r }\\n    } else {\\n        Times { attack: p.fe2_a, decay: p.fe2_d, sustain: p.fe2_s, release: p.fe2_r }\\n    }\\n}\\n\\nfn ae_times(p: &Patch, n: usize) -> Times {\\n    if n == 0 {\\n        Times { attack: p.ae1_a, decay: p.ae1_d, sustain: p.ae1_s, release: p.ae1_r }\\n    } else {\\n        Times { attack: p.ae2_a, decay: p.ae2_d, sustain: p.ae2_s, release: p.ae2_r }\\n    }\\n}\\n\\nfn lfo_settings(p: &Patch, n: usize) -> LfoSettings {\\n    let (shape, rate_hz, sync, delay, attack) = if n == 0 {\\n        (p.l1_shape, p.l1_rate, p.l1_sync, p.l1_delay, p.l1_attack)\\n    } else {\\n        (p.l2_shape, p.l2_rate, p.l2_sync, p.l2_delay, p.l2_attack)\\n    };\\n    LfoSettings { shape: Shape::from_param(shape), rate_hz, beats: lfo::beats_per_cycle(sync), delay, attack }\\n}\\n\\n#[derive(Default)]\\npub struct Voice {\\n    active: bool,\\n    /// the note counter of the note it plays (steal the smallest)\\n    age: u64,\\n    /// the note that holds it (its id; none once released)\\n    id: Option<u32>,\\n    /// the note\'s own pitch (a bend moves from here)\\n    base: f32,\\n    /// the gate is gone but the sustain pedal holds it\\n    sustained: bool,\\n    hz: f32,\\n    vel: f32,\\n    ctr: u32,\\n    osc: [Osc; 2],\\n    sub: [Sub; 2],\\n    noise: Noise,\\n    svf: [Svf; 2],\\n    coef: [Coef; 2],\\n    fenv: [Adsr; 2],\\n    aenv: [Adsr; 2],\\n    lfo: [Lfo; 2],\\n    lfo_v: [f32; 2],\\n    fe_v: [f32; 2],\\n    inc: [f64; 2],\\n    pw: [f64; 2],\\n    amp: [f32; 2],\\n    pan: [(f32, f32); 2],\\n    /// a note waiting for this voice\'s fade-out to finish (the voice was stolen)\\n    pending: Option<Note>,\\n    /// the pending note\'s gate fell before it began\\n    cancel: bool,\\n    fade: u32,\\n}\\n\\nimpl Voice {\\n    pub fn active(&self) -> bool {\\n        self.active\\n    }\\n\\n    pub fn age(&self) -> u64 {\\n        self.age\\n    }\\n\\n    pub fn id(&self) -> Option<u32> {\\n        self.id\\n    }\\n\\n    /// the pitch the note started with (Hz)\\n    pub fn base(&self) -> f32 {\\n        self.base\\n    }\\n\\n    pub fn sustained(&self) -> bool {\\n        self.sustained\\n    }\\n\\n    pub fn start(&mut self, n: Note, p: &Patch, rate: f64) {\\n        *self = Voice::default();\\n        self.active = true;\\n        self.age = n.age;\\n        self.id = Some(n.id);\\n        self.hz = n.hz.clamp(8.0, 12_000.0);\\n        self.base = self.hz;\\n        self.vel = n.vel.clamp(0.0, 1.0);\\n        self.noise = Noise::new(mix(n.seed));\\n        self.lfo[0].start(mix(n.seed ^ 1));\\n        self.lfo[1].start(mix(n.seed ^ 2));\\n        for k in 0..2 {\\n            self.fenv[k].gate_on(&fe_times(p, k), rate);\\n            self.aenv[k].gate_on(&ae_times(p, k), rate);\\n        }\\n    }\\n\\n    /// taken over by a newer note: fades out for `FADE` samples, then the note starts in its place\\n    pub fn steal(&mut self, n: Note) {\\n        self.pending = Some(n);\\n        self.cancel = false;\\n        self.fade = FADE;\\n        self.age = n.age;\\n        self.id = Some(n.id);\\n        self.base = n.hz.clamp(8.0, 12_000.0);\\n        self.sustained = false;\\n    }\\n\\n    /// a legato pitch change (a note on for a sounding id, a bend)\\n    pub fn set_pitch(&mut self, hz: f32) {\\n        let hz = hz.clamp(8.0, 12_000.0);\\n        match &mut self.pending {\\n            Some(n) => n.hz = hz,\\n            None => self.hz = hz,\\n        }\\n    }\\n\\n    /// the note off (or the pedal came up): release both envelopes\\n    pub fn release(&mut self, p: &Patch, rate: f64) {\\n        self.id = None;\\n        self.sustained = false;\\n        if self.pending.is_some() {\\n            self.cancel = true;\\n            return;\\n        }\\n        for k in 0..2 {\\n            self.fenv[k].gate_off(&fe_times(p, k), rate);\\n            self.aenv[k].gate_off(&ae_times(p, k), rate);\\n        }\\n    }\\n\\n    /// the note off came but the pedal holds the note\\n    pub fn hold(&mut self) {\\n        self.id = None;\\n        self.sustained = true;\\n    }\\n\\n    /// control rate: everything that needs `exp2`, `log2` or `tan`\\n    fn update(&mut self, p: &Patch, rate: f64) {\\n        let lfo = [f64::from(self.lfo_v[0]), f64::from(self.lfo_v[1])];\\n        let fe = [f64::from(self.fe_v[0]), f64::from(self.fe_v[1])];\\n        let vel = f64::from(self.vel);\\n        let oct = log2(f64::from(self.hz)) - log2(C4); // octaves above middle C\\n        let common = lfo[0] * f64::from(p.l1_pitch) + lfo[1] * f64::from(p.l2_pitch) + vel * f64::from(p.vel_pitch);\\n        let pwm = lfo[0] * f64::from(p.l1_pwm) + lfo[1] * f64::from(p.l2_pwm) + vel * f64::from(p.vel_pwm);\\n        let oscs = [(p.o1_semi, p.o1_fine, p.o1_key, p.o1_pw), (p.o2_semi, p.o2_fine, p.o2_key, p.o2_pw)];\\n        // oscillator 2 alone: its own envelope and LFO sends (they move it against a synced oscillator 1)\\n        let only2 = [0.0, fe[1] * f64::from(p.fe2_p2) + lfo[0] * f64::from(p.l1_p2) + lfo[1] * f64::from(p.l2_p2)];\\n        for (n, &(semi, fine, key, width)) in oscs.iter().enumerate() {\\n            let st = f64::from(semi) + f64::from(fine) / 100.0 + common + only2[n] + 12.0 * oct * f64::from(key);\\n            self.inc[n] = C4 * exp2(st / 12.0) / rate;\\n            self.pw[n] = (f64::from(width) + pwm).clamp(0.02, 0.98);\\n        }\\n        let filters = [\\n            (p.f1_cutoff, p.f1_res, p.f1_key, p.f1_env, p.f1_vel, p.f1_velres, p.l1_f1, p.l2_f1),\\n            (p.f2_cutoff, p.f2_res, p.f2_key, p.f2_env, p.f2_vel, p.f2_velres, p.l1_f2, p.l2_f2),\\n        ];\\n        for (n, &(cut, res, key, env, fvel, velres, l1, l2)) in filters.iter().enumerate() {\\n            let octaves =\\n                f64::from(key) * oct + 6.0 * f64::from(env) * fe[n] + 4.0 * f64::from(fvel) * vel + f64::from(l1) * lfo[0] + f64::from(l2) * lfo[1];\\n            let res = (f64::from(res) + f64::from(velres) * vel).clamp(0.0, 1.0) as f32;\\n            self.coef[n] = Coef::new(f64::from(cut) * exp2(octaves), res, rate);\\n        }\\n        let amps = [(p.a1_level, p.a1_pan, p.a1_vel, p.a1_key, p.l1_a1, p.l2_a1), (p.a2_level, p.a2_pan, p.a2_vel, p.a2_key, p.l1_a2, p.l2_a2)];\\n        for (n, &(level, pn, avel, key, t1, t2)) in amps.iter().enumerate() {\\n            let by_vel = (1.0 - f64::from(avel)) + f64::from(avel) * vel;\\n            let by_key = exp2(f64::from(key) * oct * 0.5).clamp(0.1, 4.0);\\n            let trem = (1.0 + 0.5 * (f64::from(t1) * (lfo[0] - 1.0) + f64::from(t2) * (lfo[1] - 1.0))).max(0.0);\\n            self.amp[n] = (f64::from(level) * by_vel * by_key * trem) as f32;\\n            self.pan[n] = pan::gains(pn);\\n        }\\n    }\\n\\n    /// One sample at the absolute `beat`: (left, right). The voice frees itself when both amp envelopes are done.\\n    pub fn render(&mut self, p: &Patch, rate: f64, beat: f64) -> (f32, f32) {\\n        let mut gain = 1.0;\\n        if let Some(n) = self.pending {\\n            self.fade -= 1;\\n            if self.fade == 0 {\\n                let cancel = self.cancel;\\n                self.start(n, p, rate);\\n                if cancel {\\n                    self.release(p, rate);\\n                }\\n            } else {\\n                gain = self.fade as f32 / FADE as f32;\\n            }\\n        }\\n        if self.ctr % CTRL == 0 {\\n            self.update(p, rate);\\n        }\\n        self.ctr = self.ctr.wrapping_add(1);\\n\\n        for k in 0..2 {\\n            self.lfo_v[k] = self.lfo[k].tick(&lfo_settings(p, k), rate, beat);\\n            self.fe_v[k] = self.fenv[k].tick(&fe_times(p, k), rate);\\n        }\\n        let ae = [self.aenv[0].tick(&ae_times(p, 0), rate), self.aenv[1].tick(&ae_times(p, 1), rate)];\\n\\n        let t1 = self.osc[0].tick(Wave::from_param(p.o1_wave), self.inc[0], self.pw[0], None);\\n        let master = if p.o2_sync >= 0.5 { t1.wrap } else { None };\\n        let t2 = self.osc[1].tick(Wave::from_param(p.o2_wave), self.inc[1], self.pw[1], master);\\n        let s1 = self.sub[0].tick(t1.wrap);\\n        let s2 = self.sub[1].tick(t2.wrap);\\n        let sources = [\\n            (t1.value * p.o1_level, p.o1_route),\\n            (s1 * p.o1_sub, p.sub1_route),\\n            (t2.value * p.o2_level, p.o2_route),\\n            (s2 * p.o2_sub, p.sub2_route),\\n            (self.noise.next() * p.noise_level, p.noise_route),\\n        ];\\n        let (mut in1, mut in2) = (0.0f32, 0.0f32);\\n        for (v, route) in sources {\\n            let route = route.round() as i32; // 0 filter 1, 1 filter 2, 2 both\\n            if route != 1 {\\n                in1 += v;\\n            }\\n            if route >= 1 {\\n                in2 += v;\\n            }\\n        }\\n        let y1 = self.svf[0].tick(&self.coef[0], Mode::from_param(p.f1_mode), svf::drive(in1, p.f1_drive));\\n        if p.f_serial >= 0.5 {\\n            in2 += p.f1_to_f2 * y1;\\n        }\\n        let y2 = self.svf[1].tick(&self.coef[1], Mode::from_param(p.f2_mode), svf::drive(in2, p.f2_drive));\\n\\n        let (a1, a2) = (y1 * ae[0] * self.amp[0] * gain, y2 * ae[1] * self.amp[1] * gain);\\n        let (l, r) = (a1 * self.pan[0].0 + a2 * self.pan[1].0, a1 * self.pan[0].1 + a2 * self.pan[1].1);\\n        if self.aenv[0].idle() && self.aenv[1].idle() && self.pending.is_none() {\\n            self.active = false;\\n        }\\n        (l, r)\\n    }\\n}\\n"}}', UTC_TIMESTAMP(), 'migration:2026-11-05-factory-modules'),
  ('fixture', 2, '{"id":"fixture","name":"fixture","factory":true,"files":{"lib.rs":"//! The conformance fixture of the module ABI (#341, #343, research/ABI-V2.md §7): one module that touches every region the\\n//! layout has – audio of 2 and 5 channels each way, a control input, a control output with a `path` and a plain one,\\n//! an event input and output, a declared variable, a sensor it `wants`, an asset slot, a factory preset – and that\\n//! misbehaves on request (its `mode`). Not an instrument. What it plays:\\n//! - `out` (2 ch): `in` + 0.25 + `bias`, per channel and frame.\\n//! - `wide_out` (5 ch): channel c = `wide_in` channel c × (c + 1); channel 4 adds the `sample` asset\'s first channel\\n//!   (silence while the slot is not ready).\\n//! - `level` (path `fx:@gain`) = the control input `push` × 2, written every call; `tilt` = the motion sensor\'s accel x\\n//!   when it is live or replayed, else not written (the consumer holds); `info` = bpm / 100 + variable `fx.level` + the\\n//!   beat at the call\'s first frame / 1000.\\n//! - `echo`: every note of `notes` again, id + 1000 (capacity 4: more are dropped and counted).\\n//!\\n//! `mode`: 0 play · 1 panic · 2 a loop that never returns · 3 allocate in the call · 4 allocate 8 MiB in the call\\n//! (the memory is frozen: the allocation fails, a trap) · 5 log 50 lines a call · 6 spin `work` × 1000 steps first.\\n#![allow(clippy::duplicated_attributes)]\\nuse deck_module::log;\\nuse deck_module::{Block, Ctx, Ev, Kind, Module};\\n\\n#[derive(Module)]\\n#[module(name = \\"fixture\\", wants = \\"motion\\", doc = \\"the module ABI conformance fixture\\")]\\n#[reads(\\"fx.level\\")]\\n#[asset(name = \\"sample\\", kind = \\"pcm\\", max_bytes = 65536, doc = \\"played on wide_out channel 4\\")]\\n#[preset(name = \\"init\\", doc = \\"a little bias\\", values(bias = 0.5))]\\n#[port(input, audio, name = \\"in\\", channels = 2)]\\n#[port(input, audio, name = \\"wide_in\\", channels = 5)]\\n#[port(input, control, name = \\"push\\")]\\n#[port(input, event, name = \\"notes\\", names = \\"music.note\\", capacity = 8)]\\n#[port(output, audio, name = \\"out\\", channels = 2)]\\n#[port(output, audio, name = \\"wide_out\\", channels = 5)]\\n#[port(output, control, name = \\"level\\", path = \\"fx:@gain\\", mode = \\"set\\")]\\n#[port(output, control, name = \\"tilt\\")]\\n#[port(output, control, name = \\"info\\")]\\n#[port(output, event, name = \\"echo\\", names = \\"music.note\\", capacity = 4)]\\npub struct Fixture {\\n    #[param(choices = \\"play|panic|loop|alloc|grow|chatty|work\\", default = 0, doc = \\"how the fixture behaves\\")]\\n    pub mode: f32,\\n    #[param(range = -1.0..1.0, default = 0.0, doc = \\"added to out\\")]\\n    pub bias: f32,\\n    #[param(range = 0.0..1000000.0, default = 0.0, doc = \\"mode 6: thousands of spin steps\\")]\\n    pub work: f32,\\n}\\n\\nfn spin(steps: u64) -> u64 {\\n    let mut n = 0u64;\\n    for i in 0..steps {\\n        n = core::hint::black_box(n.wrapping_mul(6364136223846793005).wrapping_add(i));\\n    }\\n    n\\n}\\n\\nimpl Module for Fixture {\\n    /// a heap with room to spare before the memory is frozen: a stray small allocation in a show is then served and\\n    /// counted (mode 3); one that needs more memory fails – a trap, a restart (mode 4)\\n    fn init(&mut self, _: &Ctx) {\\n        drop(core::hint::black_box(Vec::<u8>::with_capacity(256 << 10)));\\n    }\\n\\n    fn process(&mut self, block: &mut Block, ctx: &Ctx) {\\n        match self.mode as u32 {\\n            1 => panic!(\\"boom {}\\", ctx.seed()),\\n            2 => loop {\\n                core::hint::black_box(spin(1 << 20));\\n            },\\n            3 => {\\n                core::hint::black_box(vec![1u8; 16]);\\n            }\\n            4 => {\\n                core::hint::black_box(vec![1u8; 8 << 20]);\\n            }\\n            5 => {\\n                for i in 0..50 {\\n                    log!(\\"line {i}\\");\\n                }\\n            }\\