-- an earlier published version of a factory key becomes history (only where the factory row is ours)
UPDATE `entity_versions` SET `status` = 'draft'
 WHERE `entity_key` IN ('module:walk', 'module:analog', 'module:fixture') AND `status` = 'published'
   AND COALESCE(`message`, '') <> 'factory module (migration 2026-11-05-factory-modules)'
   AND EXISTS (SELECT 1 FROM `catalog_modules` m WHERE CONCAT('module:', m.`id`) COLLATE utf8mb4_general_ci = `entity_versions`.`entity_key`
               AND JSON_CONTAINS(m.`data`, 'true', '$.factory'));

-- the factory content as the published version (the creator's document)
INSERT INTO `entity_versions` (`entity_key`, `kind`, `toon`, `locale`, `json`, `author`, `created_at`, `status`, `message`)
SELECT CONCAT('module:', m.`id`), 'module', NULL, NULL, m.`data`, NULL, UTC_TIMESTAMP(), 'published', 'factory module (migration 2026-11-05-factory-modules)'
  FROM `catalog_modules` m
 WHERE m.`id` IN ('walk', 'analog', 'fixture') AND JSON_CONTAINS(m.`data`, 'true', '$.factory')
   AND NOT EXISTS (SELECT 1 FROM `entity_versions` e WHERE e.`entity_key` = CONCAT('module:', m.`id`) COLLATE utf8mb4_general_ci
                   AND e.`message` = 'factory module (migration 2026-11-05-factory-modules)');
